// Sözlük — SMK ve sınav materyalinde geçen az bilinen hukuki, teknik ve eski Türkçe terimler
// ara: metinde kelime başı olarak aranacak küçük harfli kökler (Türkçe küçük harf)
window.SOZLUK = [
  {k:"Adli para cezası", ara:["adli para"], anlam:"Mahkemece gün sayısı üzerinden belirlenen ve hükümlünün Devlet Hazinesine ödediği para cezası (TCK m.52); idari para cezasından farklıdır.", ornek:"Marka hakkına tecavüz eden kişi hapis ve yirmi bin güne kadar adli para cezası ile cezalandırılır.", kat:"Usul ve yaptırım", ref:"SMK m.30"},
  {k:"Akıbet", ara:["akıbet"], anlam:"Son, sonuç; bir şeyin sonunda ne olacağı.", ornek:"Sözleşmenin akıbeti hakkında mahkeme karar verir.", kat:"Eski Türkçe", es:["son","sonuç"]},
  {k:"Akit", ara:["akdedil"], anlam:"Sözleşme; iki veya daha fazla tarafın karşılıklı ve birbirine uygun irade beyanlarıyla kurulan hukuki işlem. 'Akdedilmek' sözleşme yapılmak demektir.", ornek:"Hak sahipliği, taraflar arasında akdedilen sözleşmeye göre belirlenir.", kat:"Genel hukuk", es:["sözleşme","mukavele"]},
  {k:"Aleniyet", ara:["aleniyet"], anlam:"Herkese açık ve bilinebilir olma. Sicilin aleniyeti, sicildeki kayıtların herkesçe öğrenilebilmesi ve kimsenin bunları bilmediğini ileri sürememesi demektir.", ornek:"Ticaret sicilinin aleniyeti ilan yoluyla sağlanır.", kat:"Genel hukuk", es:["açıklık","kamuya açıklık"]},
  {k:"Alt lisans", ara:["alt lisans"], anlam:"Lisans alanın, kendisine verilen lisansa dayanarak üçüncü kişiye kullanım izni vermesi. Sözleşmede aksi kararlaştırılmamışsa lisans alan alt lisans veremez (SMK m.24/3).", ornek:"Lisans sahipleri, aksi kararlaştırılmadıkça alt lisans veremez.", kat:"Marka", ref:"SMK m.24", es:["sublisans"]},
  {k:"Amblem", ara:["amblem"], anlam:"Coğrafi işaret ve geleneksel ürün adlarının tescilli olduğunu gösteren, Kurumca oluşturulan ve ürün ya da ambalajı üzerinde kullanılan işaret; coğrafi işaretlerde kullanılması zorunludur (SMK m.2/1-a).", ornek:"Coğrafi işaret amblemi, tescil edildiği adla birlikte ürün üzerinde kullanılır.", kat:"Coğrafi işaret", ref:"SMK m.2", es:["logo","simge"]},
  {k:"Andıran", ara:["andıran"], anlam:"Benzeyen, akla getiren, çağrıştıran.", ornek:"Tescil kapsamındaki ürünleri andıran ürünlerle ilgili ticari amaçlı kullanım tecavüz sayılır.", kat:"Eski Türkçe", ref:"SMK m.45", es:["benzeyen","çağrıştıran"]},
  {k:"Araştırma raporu", ara:["araştırma rapor"], anlam:"Başvuru konusuyla ilgili tekniğin bilinen durumundaki belgeleri gösteren rapor; yazılı görüşle birlikte düzenlenir ve yayımlanır (SMK m.96).", ornek:"Araştırma raporu yayımlandıktan sonra inceleme talep edilir.", kat:"Patent", ref:"SMK m.96", es:["search report"]},
  {k:"Arma", ara:["armalar","arması"], anlam:"Bir devleti, kurumu veya aileyi simgeleyen resmî işaret. Yetkili mercilerce izin verilmemiş arma, nişan veya adlandırmaları içeren işaretler tescil edilmez (SMK m.5/1-ğ).", ornek:"Tescil izni verilmemiş armaları içeren işaretler marka olarak tescil edilmez.", kat:"Marka", ref:"SMK m.5", es:["amblem","blazon"]},
  {k:"Asli değer veren şekil", ara:["asli değer","doğasından"], anlam:"Malın değerini esas olarak belirleyen şekil. Malın doğasından kaynaklanan, teknik sonuç için zorunlu olan veya mala asli değerini veren şekilleri münhasıran içeren işaretler marka olarak tescil edilmez (SMK m.5/1-e).", ornek:"Mala asli değerini veren şeklî özelliği münhasıran içeren işaret marka olarak tescil edilmez.", kat:"Marka", ref:"SMK m.5"},
  {k:"Aşikâr", ara:["aşikâr"], anlam:"Açık, belli, apaçık. Patentte, uzmanın tekniğin bilinen durumundan kolayca ulaşabileceği çözüm aşikârdır ve buluş basamağı içermez.", ornek:"Uzmana göre aşikâr olmayan buluş, buluş basamağı içerir.", kat:"Eski Türkçe", ref:"SMK m.83", es:["bariz","apaçık"]},
  {k:"Avrupa Patent Sözleşmesi", ara:["avrupa patent sözleşme"], anlam:"Avrupa Patent Ofisi (EPO) nezdinde tek başvuru ve tek inceleme sonunda, seçilen üye ülkelerde ulusal patent gibi etki doğuran Avrupa patenti alınmasını sağlayan sözleşme (EPC); Türkiye taraftır.", ornek:"Avrupa Patent Sözleşmesine göre verilen patent Türkiye'de geçerli olabilir.", kat:"Uluslararası", es:["EPC"]},
  {k:"Avrupa patenti", ara:["avrupa patent"], anlam:"EPO tarafından verilen ve verildikten sonra seçilen her üye ülkede o ülkenin ulusal patenti gibi etki doğuran patent; Türkiye'de geçerlilik için çevirinin süresinde Kuruma verilmesi gerekir.", ornek:"Avrupa patentinin Türkiye'de geçerli olması için Türkçe çevirisi Kuruma sunulmalıdır.", kat:"Uluslararası", es:["European patent"]},
  {k:"Ayırt edici nitelik", ara:["ayırt edici nitelik","ayırt edicilik"], anlam:"Bir işaretin, mal veya hizmetlerin belirli bir işletmeden geldiğini tüketiciye gösterebilme gücü. Ayırt edici niteliği bulunmayan işaretler marka olarak tescil edilmez (SMK m.5/1-b).", ornek:"Herhangi bir ayırt edici niteliğe sahip olmayan işaretler marka olarak tescil edilmez.", kat:"Marka", ref:"SMK m.5", es:["ayırt edicilik"]},
  {k:"Ayırt etme gücü", ara:["ayırt etme gücü","ayırt etme güc"], anlam:"Kişinin yaptığı davranışın anlamını ve sonuçlarını kavrayıp akla uygun biçimde hareket edebilme yeteneği. Küçük yaş, akıl hastalığı, sarhoşluk gibi durumlar bu gücü ortadan kaldırabilir (TMK m.13).", ornek:"Ayırt etme gücü bulunmayan kişinin işlemleri kural olarak hukuki sonuç doğurmaz.", kat:"Genel hukuk", es:["temyiz kudreti"]},
  {k:"Bağımlı patent", ara:["bağımlı patent","bağımlılığı"], anlam:"Ancak daha önceki bir patente tecavüz edilerek kullanılabilen sonraki patent. Sonraki buluş, büyük ölçüde ekonomik yarar sağlayan önemli bir teknik ilerleme gösteriyorsa önceki patent için zorunlu lisans istenebilir (SMK m.131).", ornek:"Patent konularının bağımlılığı hâlinde zorunlu lisans talep edilebilir.", kat:"Patent", ref:"SMK m.131"},
  {k:"Basiretli tacir", ara:["basiretli"], anlam:"Tacirin, ticari faaliyetlerinde ileriyi gören, dikkatli ve özenli bir iş insanı gibi davranma yükümlülüğü (TTK m.18/2). Tacirden sıradan bir kişiden daha yüksek özen beklenir.", ornek:"Her tacir, ticaretine ait bütün faaliyetlerinde basiretli bir iş insanı gibi hareket etmelidir.", kat:"Genel hukuk", es:["öngörülü","tedbirli"]},
  {k:"Baskın unsur", ara:["baskın unsur"], anlam:"Birden fazla öğeden oluşan bir markada tüketicinin dikkatini en çok çeken ve akılda kalan unsur; benzerlik değerlendirmesinde ağırlık verilir.", ornek:"Kelime unsuru, şekil unsuruna göre çoğu zaman baskın unsur kabul edilir.", kat:"Marka", es:["hâkim unsur"]},
  {k:"Bent", ara:["bendi","bentler","bendin"], anlam:"Bir fıkranın harfle (a, b, c, ç...) sıralanan alt bölümü; ör. m.5/1-ç.", ornek:"Birinci fıkranın (ç) bendine göre başvuru reddedilemez.", kat:"Eski Türkçe", es:["alt bölüm"]},
  {k:"Bilgilenmiş kullanıcı", ara:["bilgilenmiş kullanıcı"], anlam:"Tasarımın ayırt edici niteliği değerlendirilirken esas alınan, ilgili ürün alanını ve mevcut tasarımları ortalama tüketiciden daha iyi bilen dikkatli kullanıcı (SMK m.56/5).", ornek:"Tasarımın bilgilenmiş kullanıcı üzerinde bıraktığı genel izlenim önceki tasarımlardan farklıysa ayırt edicidir.", kat:"Tasarım", ref:"SMK m.56", es:["informed user"]},
  {k:"Bilirkişi", ara:["bilirkişi"], anlam:"Hâkimin, çözümü özel veya teknik bilgi gerektiren konularda görüşüne başvurduğu uzman kişi; raporu hâkimi bağlamaz.", ornek:"Hızlı imha prosedüründe gerekli hâllerde bilirkişi incelemesi yaptırılır.", kat:"Usul ve yaptırım", ref:"SMK m.163", es:["ehlivukuf"]},
  {k:"Birim etkili Avrupa patenti", ara:["birim etkili"], anlam:"Katılımcı AB üyesi devletlerin tamamında tek ve bütün olarak etki doğuran Avrupa patenti; Türkiye'yi kapsamaz.", ornek:"Birim etkili patent yalnızca katılımcı AB üyesi devletleri kapsar.", kat:"Uluslararası", es:["üniter patent","unitary patent"]},
  {k:"Birleşik ürün", ara:["birleşik ürün"], anlam:"Sökülüp takılma yoluyla değiştirilebilen veya yenilenebilen birden fazla parçadan oluşan ürün (ör. otomobil) (SMK m.55/3). Parçasının tasarımı ancak birleşik ürünün normal kullanımında görünür kalıyorsa korunur (SMK m.56/2).", ornek:"Parça birleşik ürüne takıldığında normal kullanımda görünür durumda olmalıdır.", kat:"Tasarım", ref:"SMK m.56", es:["karmaşık ürün"]},
  {k:"Bitki çeşidi", ara:["bitki çeşid"], anlam:"Bir veya birden fazla genotipin ortaya çıkardığı özelliklerle tanımlanan, aynı türdeki diğerlerinden en az bir özelliğiyle ayrılan ve değişmeden çoğaltılabilen en küçük taksonomik birimdeki bitki grubu (SMK m.2/1-b). Patentlenemez; 5042 sayılı Kanunla korunur.", ornek:"Bitki çeşitleri patentle değil, ıslahçı hakkıyla korunur.", kat:"Patent", ref:"SMK m.2"},
  {k:"Biyolojik materyal", ara:["biyolojik materyal"], anlam:"Genetik bilgi içeren ve kendi kendine üreyebilen ya da bir biyolojik sistemde üretilebilen herhangi bir madde (SMK m.2/1-c).", ornek:"Biyolojik materyal tarifnamede yeterince açıklanamıyorsa tevdi edilmelidir.", kat:"Patent", ref:"SMK m.2"},
  {k:"Bolar istisnası", ara:["bolar","ruhsat"], anlam:"İlaçların ruhsatlandırılması için gerekli test ve deneylerin patent süresi içinde yapılmasının patente tecavüz sayılmaması (SMK m.85/3-c). Böylece jenerik ilaç patent bitince hemen piyasaya girebilir.", ornek:"İlaçların ruhsatlandırılması için gerekli test ve deneyler patent hakkının kapsamı dışındadır.", kat:"Patent", ref:"SMK m.85"},
  {k:"Bölünmüş başvuru", ara:["bölünmüş başvuru"], anlam:"Buluş bütünlüğü bulunmayan bir başvurudan ayrılarak yapılan ve ilk başvurunun tarihini ve varsa rüçhan hakkını koruyan yeni başvuru (SMK m.91).", ornek:"Bölünmüş başvuru, ilk başvurunun başvuru tarihinden yararlanır.", kat:"Patent", ref:"SMK m.91", es:["ayrılmış başvuru"]},
  {k:"Budapeşte Antlaşması", ara:["budapeşte"], anlam:"Patent işlemleri amacıyla mikroorganizma tevdiinin uluslararası tanınmasını sağlar; tek bir uluslararası tevdi kuruluşuna yapılan tevdi tüm taraf ülkelerde geçerli sayılır.", ornek:"Budapeşte Antlaşması uyarınca yapılan tek tevdi, tüm taraf devletlerde kabul edilir.", kat:"Uluslararası"},
  {k:"Buluş basamağı", ara:["buluş basamağ"], anlam:"Buluşun, ilgili teknik alandaki uzmana göre tekniğin bilinen durumundan aşikâr bir şekilde çıkarılamaması. Patent için aranır; faydalı modelde aranmaz (SMK m.83).", ornek:"İlgili olduğu teknik alandaki uzmana göre aşikâr olmayan buluşun buluş basamağı içerdiği kabul edilir.", kat:"Patent", ref:"SMK m.83", es:["inventive step","tekniğe katkı"]},
  {k:"Buluş bütünlüğü", ara:["buluş bütünlüğü"], anlam:"Bir patent başvurusunun tek bir buluşa veya tek bir genel buluş fikri oluşturacak şekilde bağlantılı buluşlar grubuna ilişkin olması şartı (SMK m.91).", ornek:"Buluş bütünlüğü bulunmayan başvuru bölünmüş başvurulara ayrılabilir.", kat:"Patent", ref:"SMK m.91", es:["unity of invention"]},
  {k:"Buluşun dolaylı kullanımı", ara:["dolaylı kullanım"], anlam:"Patentli buluşun esaslı unsuruna ilişkin araçların, buluşun uygulanmasında kullanılacağı bilinerek yetkisiz kişilere sağlanması; patent sahibi bunu önleyebilir (SMK m.86).", ornek:"Patent sahibi, buluşun dolaylı kullanımını önleme hakkına sahiptir.", kat:"Patent", ref:"SMK m.86"},
  {k:"Cebri artırma", ara:["cebri"], anlam:"Borcunu ödemeyen kişinin haczedilen malının icra dairesince açık artırmayla zorla satılması.", ornek:"Cebri artırmayla yapılan satışlarda önalım hakkı kullanılamaz.", kat:"Usul ve yaptırım", ref:"SMK m.148", es:["zorla satış","icra yoluyla satış"]},
  {k:"Cenin", ara:["cenin"], anlam:"Ana rahmindeki, henüz doğmamış çocuk. Sağ doğmak koşuluyla ana rahmine düştüğü andan itibaren hak ehliyetine sahip sayılır (TMK m.28).", ornek:"Cenin, sağ doğmak koşuluyla mirasçı olabilir.", kat:"Genel hukuk", es:["dölüt"]},
  {k:"Ciddi kullanım", ara:["ciddi kullanım"], anlam:"Markanın yalnızca hakkı korumak için göstermelik olarak değil, gerçekten pazarda yer edinmek amacıyla ve ekonomik olarak anlamlı biçimde kullanılması.", ornek:"Tek bir sembolik satış, markanın ciddi kullanımı sayılmayabilir.", kat:"Marka", es:["gerçek kullanım"]},
  {k:"Coğrafi işaret", ara:["coğrafi işaret"], anlam:"Belirgin bir niteliği, ünü veya diğer özellikleri bakımından kökenin bulunduğu yöre, alan, bölge veya ülke ile özdeşleşmiş ürünü gösteren işaret; menşe adı veya mahreç işareti olarak tescil edilir (SMK m.34).", ornek:"Malatya kayısısı tescilli bir coğrafi işarettir.", kat:"Coğrafi işaret", ref:"SMK m.34"},
  {k:"Çalışan buluşu", ara:["çalışan buluş"], anlam:"Çalışanın iş ilişkisi sürerken yaptığı buluş; hizmet buluşu veya serbest buluş olabilir (SMK m.113).", ornek:"Çalışan buluşları, hizmet buluşu ve serbest buluş olarak ikiye ayrılır.", kat:"Patent", ref:"SMK m.113"},
  {k:"Çoklu başvuru", ara:["çoklu başvuru"], anlam:"Birden fazla tasarımın tek bir başvuruda birlikte tescilinin istenmesi (SMK m.61).", ornek:"Yayım erteleme hükümleri çoklu başvurudaki tasarımların bir kısmı için de uygulanabilir.", kat:"Tasarım", ref:"SMK m.61"},
  {k:"Def'i", ara:["def'i"], anlam:"Davalının, davacının hakkını inkâr etmeden, onun yerine getirilmesini engelleyen kendi hakkını ileri sürmesi (ör. zamanaşımı def'i, kullanmama def'i). Hâkim def'iyi kendiliğinden dikkate almaz.", ornek:"Kullanım ispatı, hükümsüzlük ve tecavüz davalarında def'i olarak ileri sürülür.", kat:"Usul ve yaptırım", es:["savunma hakkı"]},
  {k:"Delil tespiti", ara:["delillerin tespit"], anlam:"Dava açılmadan önce veya dava sırasında, kaybolma ya da ispatı güçleşme tehlikesi bulunan delillerin mahkemece önceden incelenip kayda geçirilmesi.", ornek:"Hak sahibi, tazminat davası açmadan önce delillerin tespitini isteyebilir.", kat:"Usul ve yaptırım", ref:"SMK m.150"},
  {k:"Deneme amaçlı kullanım", ara:["deneme amaç"], anlam:"Patentli buluşun yalnızca deneme ve araştırma amacıyla kullanılması; patent hakkının kapsamı dışında kalır (SMK m.85/3-b).", ornek:"Patent konusu buluşu içeren deneme amaçlı fiiller patent hakkının kapsamı dışındadır.", kat:"Patent", ref:"SMK m.85"},
  {k:"Denetim mercii", ara:["denetim merci","kullanımın denetim"], anlam:"Coğrafi işaretli ürünlerin tescilde belirtilen özelliklere uygun üretilip üretilmediğini denetleyen yetkili kuruluş (SMK m.49).", ornek:"Kullanımın denetimi, tescilde belirtilen denetim mercii tarafından yapılır.", kat:"Coğrafi işaret", ref:"SMK m.49"},
  {k:"Derdest", ara:["derdest"], anlam:"Görülmekte olan, henüz sonuçlanmamış (dava). Aynı konuda derdest bir dava varken ikinci bir dava açılamaz.", ornek:"İhtisas mahkemelerinde derdest olan davaların görülmesine devam olunur.", kat:"Usul ve yaptırım", ref:"SMK geçici m.6", es:["görülmekte olan","bekleyen"]},
  {k:"Dönüştürme", ara:["dönüştürme","dönüştürül"], anlam:"Bir başvurunun başka bir koruma türüne çevrilmesi; ör. patent başvurusunun faydalı model başvurusuna veya tersine dönüştürülmesi (SMK m.104). Madrid sisteminde düşen uluslararası tescilin ulusal başvurulara dönüştürülmesi de aynı adı taşır.", ornek:"Faydalı model başvurusunun patent başvurusuna dönüştürülmesi talep edilebilir.", kat:"Patent", ref:"SMK m.104", es:["çevirme"]},
  {k:"Dünya Ticaret Örgütü", ara:["dünya ticaret örgütü"], anlam:"Uluslararası ticaret kurallarını belirleyen örgüt (DTÖ/WTO); TRIPS kuruluş anlaşmasının ekidir. DTÖ üyesi ülkelerdeki başvurular da rüçhan hakkı doğurur (SMK m.3, m.12).", ornek:"Dünya Ticaret Örgütü Kuruluş Anlaşması hükümleri dâhilinde başvuru hakkına sahip kişiler korumadan yararlanır.", kat:"Uluslararası", ref:"SMK m.3", es:["DTÖ","WTO"]},
  {k:"Dürüstlük kuralı", ara:["dürüstlük"], anlam:"Herkesin haklarını kullanırken ve borçlarını yerine getirirken uyması gereken, makul ve dürüst bir insandan beklenen davranış ölçüsü (TMK m.2). Objektif iyiniyet olarak da adlandırılır.", ornek:"Bir hakkın açıkça kötüye kullanılmasını hukuk düzeni korumaz; dürüstlük kuralı bunu gerektirir.", kat:"Genel hukuk", es:["objektif iyiniyet","hüsnüniyet kuralı"]},
  {k:"Düstur", ara:["düstur"], anlam:"Kanun ve diğer mevzuatın toplandığı resmî derleme; ayrıca ilke, kural anlamına gelir.", ornek:"Yayımlandığı Düstur: Tertip 5, Cilt 58.", kat:"Eski Türkçe", es:["kanunlar derlemesi","ilke"]},
  {k:"Ek patent", ara:["ek patent"], anlam:"Asıl patent başvurusu konusu buluşu geliştiren veya mükemmelleştiren buluş için asıl başvuruya bağlı olarak yapılan patent başvurusu; süresi asıl patentin bitimine kadardır ve yıllık ücret ödenmez (SMK m.123).", ornek:"Ek patent başvuruları ve ek patent için yıllık ücret ödenmez.", kat:"Patent", ref:"SMK m.123"},
  {k:"Elkoyma", ara:["elkoy","elkonul"], anlam:"Bir mala, sahibinin tasarrufunu engelleyecek şekilde resmî makamlarca el konulması. Tecavüz ürünlerine ve bunların üretiminde kullanılan araçlara elkonulabilir (SMK m.149, m.159).", ornek:"Tecavüz ürünlerine bulundukları her yerde elkonulmasına karar verilebilir.", kat:"Usul ve yaptırım", ref:"SMK m.159", es:["zapt","el koyma"]},
  {k:"Embriyo", ara:["embriyo"], anlam:"Döllenmeden sonra gelişiminin ilk evresindeki canlı. İnsan embriyosunun sınai veya ticari amaçlarla kullanılması patentlenemez (SMK m.82/3-d).", ornek:"İnsan embriyosunun ticari amaçlarla kullanılmasına patent verilmez.", kat:"Patent", ref:"SMK m.82", es:["oğulcuk"]},
  {k:"Emredici hüküm", ara:["emredici"], anlam:"Tarafların sözleşmeyle aksini kararlaştıramayacağı, mutlaka uyulması gereken kanun hükmü. Buna aykırı sözleşme hükümleri geçersizdir.", ornek:"Çalışan ile işveren arasındaki sözleşmeler, çalışan buluşlarıyla ilgili emredici hükümlere aykırı olamaz.", kat:"Genel hukuk", es:["buyurucu hüküm","amir hüküm"]},
  {k:"En çok kayrılan ulus", ara:["en çok kayrılan"], anlam:"TRIPS'te, bir üyenin herhangi bir ülke vatandaşına tanıdığı avantaj, ayrıcalık, imtiyaz veya muafiyetin diğer tüm üyelerin vatandaşlarına da derhal ve koşulsuz tanınması ilkesi (TRIPS m.4).", ornek:"En çok kayrılan ulus ilkesi Paris Sözleşmesinde değil TRIPS'te yer alır.", kat:"Uluslararası", es:["MFN","en ziyade müsaadeye mazhar millet"]},
  {k:"Erginlik", ara:["ergin"], anlam:"Kişinin tam fiil ehliyetine kavuşması için gereken olgunluk; on sekiz yaşın doldurulmasıyla başlar, evlenmeyle de kazanılır (TMK m.11).", ornek:"Erginlik on sekiz yaşın doldurulmasıyla başlar.", kat:"Genel hukuk", es:["reşit olma","rüşt"]},
  {k:"Esas olarak biyolojik işlem", ara:["esas olarak biyolojik"], anlam:"Melezleme veya seleksiyon gibi tamamen doğal olaylardan oluşan bitki ya da hayvan üretim usulü; patentlenemez (SMK m.82/3-b, m.82/5).", ornek:"Bitki veya hayvan üretimine yönelik esas olarak biyolojik işlemlere patent verilmez.", kat:"Patent", ref:"SMK m.82"},
  {k:"Eşdeğer unsur", ara:["eşdeğer"], anlam:"Patent tecavüzü değerlendirmesinde, istemdeki bir unsurla esasen aynı işlevi gören ve aynı sonucu sağlayan unsur; koruma kapsamı belirlenirken eşdeğer unsurlar da dikkate alınır (SMK m.89).", ornek:"Koruma kapsamı belirlenirken istemlerde belirtilen unsurlara eşdeğer olan unsurlar da dikkate alınır.", kat:"Patent", ref:"SMK m.89", es:["muadil"]},
  {k:"Eşey hattı", ara:["eşey hattı"], anlam:"İnsanın üreme hücreleri yoluyla nesilden nesle aktarılan genetik soy hattı. İnsan eşey hattının genetik kimliğini değiştirme işlemleri patentlenemez (SMK m.82/3-d).", ornek:"İnsan eşey hattının genetik kimliğini değiştirme işlemlerine patent verilmez.", kat:"Patent", ref:"SMK m.82", es:["germ hattı","üreme hattı"]},
  {k:"Etkin pişmanlık", ara:["etkin pişmanlık"], anlam:"Suç işleyen kişinin suçun ortaya çıkmasına veya zararın giderilmesine yardım etmesi nedeniyle cezasız kalması ya da cezasının indirilmesi. Taklit malı satan kişi malı nereden temin ettiğini bildirip üreticilerin yakalanmasını sağlarsa ceza almaz (SMK m.30/7).", ornek:"Taklit malı nereden aldığını bildirerek üreticinin yakalanmasını sağlayan satıcıya ceza verilmez.", kat:"Usul ve yaptırım", ref:"SMK m.30"},
  {k:"EUIPO", ara:["euıpo"], anlam:"Avrupa Birliği Fikrî Mülkiyet Ofisi; AB markası ve tescilli topluluk tasarımı başvurularını inceleyip tescil eden kurum (eski adı OHIM).", ornek:"Kılavuz, EUIPO ve ATAD içtihadından yararlanır.", kat:"Uluslararası", es:["AB Fikrî Mülkiyet Ofisi","OHIM"]},
  {k:"Faydalı model", ara:["faydalı model"], anlam:"Yeni ve sanayiye uygulanabilir buluşlara verilen, buluş basamağı aranmayan ve on yıl koruma sağlayan hak. Usuller, kimyasal, biyolojik ve eczacılıkla ilgili buluşlar faydalı modelle korunmaz (SMK m.142).", ornek:"Faydalı modelin koruma süresi on yıldır ve uzatılamaz.", kat:"Patent", ref:"SMK m.142", es:["küçük patent"]},
  {k:"Ferî", ara:["ferileri"], anlam:"İkincil, asıl olana bağlı olan. 'İlamın ferileri', hükümle birlikte istenebilen faiz ve yargılama giderleri gibi yan alacaklardır.", ornek:"Bu hüküm, ilamın ferileri hakkında da uygulanır.", kat:"Eski Türkçe", es:["tali","yan","ikincil"]},
  {k:"Fıkra", ara:["fıkra"], anlam:"Kanun maddesinin parantez içinde rakamla numaralanan bölümü, paragrafı; ör. m.5/2, 5. maddenin 2. fıkrasıdır.", ornek:"Birinci fıkranın (b) bendi uyarınca başvuru reddedilir.", kat:"Eski Türkçe", es:["paragraf"]},
  {k:"Fiil ehliyeti", ara:["fiil ehliyet"], anlam:"Kişinin kendi işlemleriyle hak edinip borç altına girebilme yeteneği. Ayırt etme gücüne sahip, ergin ve kısıtlı olmayan kişi tam fiil ehliyetlidir (TMK m.10).", ornek:"Fiil ehliyetine sahip olan kişi, kendi fiilleriyle hak edinebilir ve borç altına girebilir.", kat:"Genel hukuk", es:["medeni hakları kullanma ehliyeti"]},
  {k:"Fikrî ve Sınai Haklar Mahkemesi", ara:["fikri ve sınai haklar"], anlam:"SMK'dan doğan davalara bakmakla görevli ihtisas mahkemesi (hukuk ve ceza). Kurulmamış yerlerde davalara asliye hukuk veya asliye ceza mahkemesi bakar (SMK m.156).", ornek:"Kurul kararlarına karşı Ankara Fikrî ve Sınai Haklar Hukuk Mahkemesinde dava açılır.", kat:"Usul ve yaptırım", ref:"SMK m.156", es:["FSHHM","ihtisas mahkemesi"]},
  {k:"Gaiplik", ara:["gaiplik"], anlam:"Ölüm tehlikesi içinde kaybolan veya uzun süredir kendisinden haber alınamayan kişinin, ilgililerin istemiyle mahkeme kararıyla ölmüş gibi kabul edilmesi (TMK m.32-35).", ornek:"Ölüm tehlikesinde kaybolmadan itibaren en az bir yıl geçince gaiplik kararı istenebilir.", kat:"Genel hukuk", es:["kayıplık"]},
  {k:"Garanti markası", ara:["garanti marka"], anlam:"Marka sahibinin kontrolü altında birçok işletme tarafından, o işletmelerin mallarının ortak özelliklerini, üretim usullerini, coğrafi menşelerini ve kalitesini garanti etmeye yarayan işaret. Marka sahibi veya ona iktisaden bağlı işletme bu markayı kullanamaz (SMK m.31).", ornek:"Garanti markasının marka sahibinin mal veya hizmetlerinde kullanılması yasaktır.", kat:"Marka", ref:"SMK m.31", es:["sertifika markası"]},
  {k:"Gasp (patent / tasarım)", ara:["gaspı","gaspın"], anlam:"Hak sahibi olmayan kişinin başkasına ait buluş veya tasarım için başvuru yapması ya da tescil ettirmesi. Gerçek hak sahibi başvurunun veya hakkın kendisine devrini mahkemeden isteyebilir (SMK m.71, m.111).", ornek:"Patentin gaspı hâlinde gerçek hak sahibi, patentin kendisine devrini dava yoluyla isteyebilir.", kat:"Patent", ref:"SMK m.111", es:["haksız sahiplenme"]},
  {k:"Geleneksel ürün adı", ara:["geleneksel ürün adı"], anlam:"Menşe adı veya mahreç işareti kapsamına girmeyen, bir ürünü tarif etmek için en az otuz yıldır geleneksel olarak kullanıldığı kanıtlanan ve geleneksel üretim yöntemi/bileşim ya da geleneksel hammaddeden kaynaklanan ad (SMK m.34/3).", ornek:"Geleneksel ürün adı için adın en az otuz yıl süreyle kullanıldığı kanıtlanmalıdır.", kat:"Coğrafi işaret", ref:"SMK m.34", es:["GÜA"]},
  {k:"Genel ahlak", ara:["genel ahlak"], anlam:"Toplumda genel kabul görmüş ahlak anlayışı ve değerleri. Genel ahlaka aykırı işaretler marka olarak tescil edilmez (SMK m.5/1-ı).", ornek:"Müstehcen ifadeler içeren işaretler genel ahlaka aykırı bulunarak reddedilir.", kat:"Genel hukuk", ref:"SMK m.5"},
  {k:"Genel izlenim", ara:["genel izlenim"], anlam:"Bir işaretin veya tasarımın ayrıntılara inilmeden bütün olarak bıraktığı etki. Marka benzerliği ve tasarımın ayırt ediciliği genel izlenime göre değerlendirilir (SMK m.56/5).", ornek:"Tasarımın bilgilenmiş kullanıcı üzerinde bıraktığı genel izlenim, önceki tasarımlarınkinden farklı olmalıdır.", kat:"Marka", ref:"SMK m.56"},
  {k:"Gizli patent", ara:["gizli patent"], anlam:"Millî güvenlik açısından önemli görülen buluşlara ilişkin, Millî Savunma Bakanlığının kararıyla gizli yürütülen patent başvurusu; gizli kaldığı sürece yıllık ücret ödenmez ve sahibi Devletten tazminat isteyebilir (SMK m.124).", ornek:"Gizli patent başvurusu sahibi, buluşu yetkisi olmayan kişilere açıklayamaz.", kat:"Patent", ref:"SMK m.124"},
  {k:"Görevli ve yetkili mahkeme", ara:["görevli ve yetkili","yetkili mahkeme"], anlam:"Görev, davaya hangi tür mahkemenin bakacağını (ör. fikrî ve sınai haklar hukuk mahkemesi); yetki ise hangi yerdeki mahkemenin bakacağını belirtir (SMK m.156).", ornek:"Kurum kararlarına karşı açılacak davalarda görevli ve yetkili mahkeme Ankara Fikrî ve Sınai Haklar Hukuk Mahkemesidir.", kat:"Usul ve yaptırım", ref:"SMK m.156"},
  {k:"Güvenlik tedbiri", ara:["güvenlik tedbir"], anlam:"Ceza dışındaki ceza hukuku yaptırımı. Tüzel kişilere ceza verilemez; suç tüzel kişinin faaliyeti çerçevesinde işlenmişse ona özgü güvenlik tedbirlerine (faaliyet izninin iptali, müsadere) hükmolunur (TCK m.60).", ornek:"Suçun bir tüzel kişinin faaliyeti çerçevesinde işlenmesi hâlinde güvenlik tedbirlerine hükmolunur.", kat:"Usul ve yaptırım", ref:"SMK m.30"},
  {k:"Hak düşürücü süre", ara:["hak düşürücü"], anlam:"Geçmesiyle hakkın kendisinin tamamen sona erdiği süre; zamanaşımından farklı olarak hâkim tarafından kendiliğinden dikkate alınır. Ör. tasarım gaspında üç yıllık talep süresi (SMK m.71/3).", ornek:"Gerçek hak sahibi olmayan kişi kötüniyetliyse hak düşürücü süre uygulanmaz.", kat:"Usul ve yaptırım", ref:"SMK m.71", es:["süreye bağlı hak kaybı"]},
  {k:"Hak ehliyeti", ara:["hak ehliyet"], anlam:"Haklara ve borçlara sahip olabilme yeteneği. Her insan sağ doğmak koşuluyla hak ehliyetine sahiptir; tüzel kişiler de insana özgü olanlar dışındaki haklara ehildir.", ornek:"Tüzel kişiler cins, yaş, hısımlık gibi insana özgü nitelikler dışında tüm haklara ehildir.", kat:"Genel hukuk", es:["medeni haklardan yararlanma ehliyeti"]},
  {k:"Hakkaniyet", ara:["hakkaniyet"], anlam:"Somut olayın özelliklerine göre adil ve makul olan çözüm ölçüsü; hâkimin takdir yetkisini kullanırken başvurduğu adalet anlayışı.", ornek:"Ödenmiş lisans bedelinin hakkaniyet gereği kısmen veya tamamen iadesi istenebilir.", kat:"Genel hukuk", ref:"SMK m.27", es:["hak ve nısfet","adalet"]},
  {k:"Hakkın kötüye kullanılması", ara:["hakkın kötüye","kötüye kullan"], anlam:"Bir hakkın amacı dışında, yalnızca başkasına zarar vermek gibi dürüstlüğe aykırı biçimde kullanılması. Bir hakkın açıkça kötüye kullanılmasını hukuk düzeni korumaz (TMK m.2/2).", ornek:"Yalnızca rakibini engellemek için alınan bir tescile dayanmak, hakkın kötüye kullanılması sayılabilir.", kat:"Genel hukuk", es:["hakkın suiistimali"]},
  {k:"Hakkın tüketilmesi", ara:["tüketil","tükenme"], anlam:"Korunan ürün, hak sahibi veya onun izniyle piyasaya sunulduktan sonra o ürünle ilgili sonraki fiillerin (yeniden satış gibi) hakkın kapsamı dışında kalması; ancak marka sahibi ürünün değiştirilerek veya kötüleştirilerek kullanılmasını önleyebilir (SMK m.152).", ornek:"Hak sahibinin izniyle piyasaya sunulan ürünün yeniden satışı hakkın tüketilmesi nedeniyle tecavüz değildir.", kat:"Usul ve yaptırım", ref:"SMK m.152", es:["hakkın tükenmesi","exhaustion"]},
  {k:"Hakların yeniden tesisi", ara:["yeniden tesis"], anlam:"Gerekli özeni göstermesine rağmen bir süreye uyamayan ve hak kaybına uğrayan kişinin, engelin kalkmasından itibaren iki ay içinde (sürenin bitiminden itibaren en geç bir yıl) ücret ödeyerek kaybettiği hakları geri istemesi (SMK m.107/2).", ornek:"Talebin kabulü hâlinde süreye uyulmamış olmanın sonuçları doğmamış sayılır.", kat:"Usul ve yaptırım", ref:"SMK m.107", es:["eski hâle getirme","restitutio in integrum"]},
  {k:"Haksız rekabet", ara:["haksız rekabet"], anlam:"Rakipler arasında veya tedarikçilerle müşteriler arasındaki ilişkileri etkileyen, aldatıcı ya da dürüstlük kuralına başka şekilde aykırı davranış ve ticari uygulamalar (TTK m.54-55). Tescilli bir hak olmasa da bu hükümlerle koruma sağlanabilir.", ornek:"Başkasının ürünlerine karıştırılacak kadar benzeyen ambalaj kullanmak haksız rekabet oluşturur.", kat:"Genel hukuk"},
  {k:"Halef", ara:["halef"], anlam:"Bir kişinin hak ve yükümlülüklerini devralan kişi. Mirasçı gibi bütün malvarlığını devralana külli halef, yalnızca belirli bir hakkı devralana cüzi halef denir.", ornek:"Patent isteme hakkı, buluşu yapana veya halefine aittir.", kat:"Genel hukuk", ref:"SMK m.109", es:["ardıl","hak sahibinin yerine geçen"]},
  {k:"Halel", ara:["halel"], anlam:"Zarar, bozukluk, eksiklik. 'Halel getirmez', etkilemez, zarar vermez demektir.", ornek:"Bu hüküm, önceki tarihli haklara halel getirmez.", kat:"Eski Türkçe", es:["zarar","eksiklik"]},
  {k:"Hısımlık", ara:["hısımlık"], anlam:"Kan bağıyla (kan hısımlığı) veya evlilik yoluyla (kayın hısımlığı) kurulan akrabalık ilişkisi.", ornek:"Tüzel kişiler, cins, yaş ve hısımlık gibi insana özgü niteliklere bağlı haklardan yararlanamaz.", kat:"Genel hukuk", es:["akrabalık"]},
  {k:"Hizmet buluşu", ara:["hizmet buluş"], anlam:"Çalışanın işletmedeki görevi gereği yaptığı veya büyük ölçüde işletmenin deneyim ve çalışmalarına dayanan buluş. İşveren tam veya kısmi hak talep edebilir; bu durumda çalışana makul bir bedel ödenir (SMK m.113-115).", ornek:"Çalışan, hizmet buluşunu gecikmeksizin ve yazılı olarak işverene bildirmekle yükümlüdür.", kat:"Patent", ref:"SMK m.113", es:["görev buluşu"]},
  {k:"Hükmolunmak", ara:["hükmolun"], anlam:"Mahkemece karar verilmek, hükme bağlanmak.", ornek:"Malı nereden temin ettiğini bildiren kişi hakkında cezaya hükmolunmaz.", kat:"Eski Türkçe", ref:"SMK m.30", es:["karar verilmek"]},
  {k:"Hükümsüzlük", ara:["hükümsüz"], anlam:"Bir hakkın, tescil anında var olan bir sakatlık nedeniyle mahkeme kararıyla geçersiz sayılması; etkisi geriye yürür ve koruma hiç doğmamış sayılır (SMK m.25, m.27).", ornek:"Hükümsüzlük kararı marka başvuru tarihinden itibaren etkilidir.", kat:"Usul ve yaptırım", ref:"SMK m.25", es:["geçersizlik","butlan"]},
  {k:"Hükümsüzlük–iptal farkı", ara:["hükümsüzlük ve iptal","hükümsüzlüğün ve iptalin"], anlam:"Hükümsüzlük, tescil anında var olan bir sakatlık nedeniyle verilir ve başvuru tarihine kadar geriye yürür (koruma hiç doğmamış sayılır). İptal ise sonradan doğan bir nedenle (ör. beş yıl kullanmama) verilir ve kural olarak iptal talebinin Kuruma sunulduğu tarihten itibaren etkilidir (SMK m.27).", ornek:"Marka hükümsüzlüğüne mahkeme, iptaline ise Kurum karar verir.", kat:"Marka", ref:"SMK m.27"},
  {k:"Islahçı hakkı", ara:["ıslah"], anlam:"Yeni bir bitki çeşidini geliştiren (ıslah eden) kişiye 5042 sayılı Kanunla tanınan hak. Islahçı ile patent sahibi arasında bağımlılık varsa zorunlu lisans istenebilir (SMK m.129).", ornek:"Islahçı, önceki bir patente tecavüz etmeden yeni bitki çeşidini kullanamıyorsa zorunlu lisans isteyebilir.", kat:"Patent", ref:"SMK m.129", es:["bitki ıslahçısı hakkı"]},
  {k:"İbraz", ara:["ibraz"], anlam:"Bir belgeyi yetkili makama gösterme, sunma.", ornek:"Sergide teşhir eden kişi, markanın tasdikli örneğini ibraz etmelidir.", kat:"Eski Türkçe", es:["sunma","gösterme"]},
  {k:"İhbar", ara:["ihbar"], anlam:"Bir durumu ilgili makama veya kişiye bildirme. Davada ihbar, davanın sonucundan etkilenebilecek üçüncü kişiye davanın bildirilmesidir.", ornek:"Coğrafi işarete tecavüz nedeniyle açılan dava tescil ettirene ihbar olunur.", kat:"Usul ve yaptırım", ref:"SMK m.53", es:["bildirme"]},
  {k:"İhdas", ara:["ihdas"], anlam:"Kurma, oluşturma, yeni bir şey meydana getirme.", ornek:"Sınai Mülkiyetin Himayesine Mahsus Milletlerarası Bir İttihat İhdas Edilmesine Dair Sözleşme.", kat:"Eski Türkçe", ref:"SMK m.2", es:["kurma","oluşturma"]},
  {k:"İhmal", ara:["ihmal"], anlam:"Gereken dikkat ve özeni göstermeme; kastın dışında kalan kusur türü. 'Ağır ihmal' en basit dikkatin bile gösterilmemesidir.", ornek:"Marka sahibinin ağır ihmali nedeniyle zarar görenlerin tazminat talepleri saklıdır.", kat:"Genel hukuk", es:["özensizlik","savsaklama"]},
  {k:"İhtisas mahkemesi", ara:["ihtisas"], anlam:"Belirli bir alandaki uyuşmazlıklara bakmak üzere uzmanlaşmış mahkeme.", ornek:"Mülga KHK'lar uyarınca kurulmuş ihtisas mahkemeleri, SMK m.156'ya göre kurulan mahkemeler olarak kabul edilir.", kat:"Usul ve yaptırım", ref:"SMK geçici m.6", es:["uzmanlık mahkemesi"]},
  {k:"İhtiyati tedbir", ara:["ihtiyati tedbir","ihtiyati"], anlam:"Dava sonuçlanıncaya kadar hakkın korunması ve verilecek hükmün etkinliği için mahkemenin verdiği geçici önlem; ör. tecavüzün durdurulması, ürünlere elkonulması, teminat verilmesi (SMK m.159).", ornek:"Davacı, tecavüzün gerçekleşmekte olduğunu ispat ederek ihtiyati tedbir isteyebilir.", kat:"Usul ve yaptırım", ref:"SMK m.159", es:["geçici hukuki koruma","tedbir kararı"]},
  {k:"İkame", ara:["ikame"], anlam:"Bir şeyin yerine başka bir şeyi koyma; yerine geçen şey. Sınıf listelerinde 'ikameleri', aynı amaçla yerine kullanılan maddeler demektir.", ornek:"Kauçuk, güta perka, sakız ve bunların ikameleri 17. sınıftadır.", kat:"Eski Türkçe", es:["yerine geçen","muadil"]},
  {k:"İktibas", ara:["iktibas"], anlam:"Bir şeyi aynen alma, aynısını kullanma. Marka hukukunda başkasının markasının aynısını kullanmak demektir; iltibas ise benzerini kullanmaktır (SMK m.30).", ornek:"Başkasına ait marka hakkına iktibas veya iltibas suretiyle tecavüz eden kişi hapis ve adli para cezası alır.", kat:"Marka", ref:"SMK m.30", es:["aynen alma","kopyalama"]},
  {k:"İktisaden", ara:["iktisaden"], anlam:"Ekonomik bakımdan.", ornek:"Garanti markası, marka sahibine iktisaden bağlı işletmenin mallarında kullanılamaz.", kat:"Eski Türkçe", ref:"SMK m.31", es:["ekonomik olarak"]},
  {k:"İlanen tebligat", ara:["ilanen"], anlam:"Adresi bulunamayan kişiye yapılacak tebligatın ilan yoluyla yapılması. SMK kapsamındaki ilanen tebligatlar Bülten üzerinden yapılır ve yayımdan yedi gün sonra yapılmış sayılır (SMK m.160/7).", ornek:"İlanen tebligatlar Bültenin yayımı tarihinden yedi gün sonra yapılmış sayılır.", kat:"Usul ve yaptırım", ref:"SMK m.160", es:["ilan yoluyla tebliğ"]},
  {k:"İltibas", ara:["iltibas"], anlam:"Karıştırılma; birbirine benzetilerek yanılgıya düşürme. Marka hukukunda başkasının markasına benzer bir işaret kullanarak halkta karıştırılma ihtimali yaratmaktır (SMK m.30).", ornek:"Başkasına ait marka hakkına iltibas suretiyle tecavüz ederek mal üreten kişi cezalandırılır.", kat:"Marka", ref:"SMK m.30", es:["karıştırılma","benzetme"]},
  {k:"İmha", ara:["imhası","imha edil"], anlam:"Tecavüz ürünlerinin yok edilmesi. Hak sahibi tecavüz ürünlerinin imhasını isteyebilir; ceza soruşturmasında bozulabilir veya saklanması külfetli ürünler için hızlı imha prosedürü uygulanır (SMK m.149, m.163).", ornek:"Soruşturma aşamasında, hızlı imha prosedürüyle suç eşyası imha edilebilir.", kat:"Usul ve yaptırım", ref:"SMK m.163", es:["yok etme"]},
  {k:"İmtiyazlı alacak", ara:["imtiyaz"], anlam:"İflas veya haciz durumunda diğer alacaklardan önce ödenen ayrıcalıklı alacak. Çalışan buluşundan doğan bedel alacağı imtiyazlı alacaklardandır (SMK m.120/2).", ornek:"Çalışan buluşundan doğan bedel alacağı imtiyazlı alacaklardandır.", kat:"Genel hukuk", ref:"SMK m.120", es:["rüçhanlı alacak","öncelikli alacak"]},
  {k:"İnceleme raporu", ara:["inceleme rapor"], anlam:"Başvurunun ve buluşun patent verilmesi şartlarını taşıyıp taşımadığının değerlendirildiği rapor; olumlu sonuçlanırsa patent verilir (SMK m.98).", ornek:"İnceleme raporu olumluysa patent verilmesine karar verilir.", kat:"Patent", ref:"SMK m.98", es:["examination report"]},
  {k:"İnfaz", ara:["infaz"], anlam:"Kesinleşmiş bir mahkeme kararının, özellikle ceza hükmünün, yerine getirilmesi.", ornek:"Müsadere kararı kesinleşmiş ancak infazı gerçekleşmemiş kişiler hakkında geçici hüküm uygulanır.", kat:"Usul ve yaptırım", ref:"SMK geçici m.3", es:["yerine getirme"]},
  {k:"İnhisari", ara:["inhisari"], anlam:"Tekelci, başkalarını dışlayan; yalnızca bir kişiye tanınmış.", ornek:"Kamu yararı gerekçesiyle verilen zorunlu lisanslar inhisari olabilir.", kat:"Eski Türkçe", ref:"SMK m.132", es:["münhasır","tekelci"]},
  {k:"İnhisari lisans", ara:["inhisari lisans"], anlam:"Lisans verenin başkasına lisans veremediği ve hakkını açıkça saklı tutmadıkça kendisinin de kullanamadığı lisans. Sözleşmede aksi kararlaştırılmamışsa lisans inhisari değildir (SMK m.24/2).", ornek:"İnhisari lisans sözleşmelerinde lisans veren, başkasına lisans veremez.", kat:"Marka", ref:"SMK m.24", es:["münhasır lisans","tekelci lisans"]},
  {k:"İnhisari olmayan lisans", ara:["inhisari olmayan"], anlam:"Lisans verenin hem kendisinin kullanabildiği hem de üçüncü kişilere başka lisanslar verebildiği lisans; aksi kararlaştırılmadıkça lisans bu türdendir (SMK m.24/2).", ornek:"İnhisari olmayan lisans sözleşmelerinde lisans veren, başkalarına da lisans verebilir.", kat:"Marka", ref:"SMK m.24", es:["basit lisans","münhasır olmayan lisans"]},
  {k:"İntikal", ara:["intikal"], anlam:"Bir hakkın, özellikle miras yoluyla, kendiliğinden başka bir kişiye geçmesi.", ornek:"Sınai mülkiyet hakkı miras yoluyla intikal edebilir.", kat:"Genel hukuk", ref:"SMK m.148", es:["geçme","miras yoluyla geçiş"]},
  {k:"İptal (marka)", ara:["iptal"], anlam:"Geçerli olarak doğmuş bir marka hakkının, sonradan ortaya çıkan bir nedenle (haklı neden olmaksızın beş yıl kullanmama, ortak ad hâline gelme, halkı yanıltıcı hâle gelme, şartnameye aykırı kullanım) Kurum kararıyla sona erdirilmesi (SMK m.26).", ornek:"Tescil tarihinden itibaren beş yıl içinde haklı neden olmaksızın kullanılmayan marka iptal edilir.", kat:"Marka", ref:"SMK m.26"},
  {k:"İradi / mecburi", ara:["iradi","mecburi"], anlam:"İradi: kişinin kendi isteğiyle yaptığı. Mecburi: zorunlu, kişinin iradesi dışında gerçekleşen (ör. haciz, miras).", ornek:"Sınai mülkiyet hakkını etkileyen iradi veya mecburi tasarruflar sicile kaydedilir.", kat:"Eski Türkçe", es:["isteğe bağlı / zorunlu"]},
  {k:"İspat yükü", ara:["ispat yük"], anlam:"Bir iddiayı kanıtlama zorunluluğunun hangi tarafa ait olduğu; kural olarak iddia eden ispat eder (TMK m.6). Usul patentinde, aynı ürünün patentli usulle elde edildiği kabul edilir ve aksini davalı ispat eder.", ornek:"Usul patentine tecavüz davasında ispat yükü davalıya geçebilir.", kat:"Usul ve yaptırım", es:["kanıtlama yükü"]},
  {k:"İstem", ara:["istemler","istemin","bağımsız istem"], anlam:"Patent başvurusunda korunması istenen teknik özellikleri tanımlayan ifadeler. Patentin koruma kapsamı istemlerle belirlenir; tarifname ve resimler istemlerin yorumunda kullanılır (SMK m.89). Bağımsız istem buluşu tek başına tanımlar; bağımlı istem bir başka isteme atıf yaparak ek özellik getirir.", ornek:"Patent korumasının kapsamı istemlerle belirlenir.", kat:"Patent", ref:"SMK m.89", es:["claim","patent istemi"]},
  {k:"İşlemlerin devam ettirilmesi", ara:["devam ettiril"], anlam:"Patent başvurusunda bir süreye uyulmaması hâlinde, bunun sonucunun bildiriminden itibaren iki ay içinde ücret ödenerek işlemlere devam edilmesinin istenmesi (SMK m.107/1).", ornek:"Başvuru sahibi, bildirim tarihinden itibaren iki ay içinde işlemlerin devam ettirilmesini talep edebilir.", kat:"Usul ve yaptırım", ref:"SMK m.107"},
  {k:"İşletme adı", ara:["işletme adı"], anlam:"Bir işletmeyi tanıtmaya yarayan, ticaret unvanından ayrı ad; tacire değil işletmeye ilişkindir (TTK m.52).", ornek:"İşletme adı, ticaret unvanıyla karıştırılmayacak şekilde kullanılmalıdır.", kat:"Genel hukuk"},
  {k:"İştigal", ara:["iştigal"], anlam:"Bir işle uğraşma, meşgul olma.", ornek:"Tekel sahibi iştigal ettiği sanayi alanında ekonomik zarara uğrayabilir.", kat:"Eski Türkçe", ref:"SMK m.88", es:["uğraşma"]},
  {k:"İtibar (marka)", ara:["itibarın","itibarına"], anlam:"Bir markanın kamuoyunda kazandığı ün ve olumlu algı. Önceki markanın itibarından haksız yararlanacak, itibarına zarar verecek veya ayırt edici karakterini zedeleyecek başvurular, mallar farklı olsa bile itiraz üzerine reddedilir (SMK m.6/5).", ornek:"Sınai mülkiyet hakkının itibarı zarara uğrarsa ayrıca tazminat istenebilir.", kat:"Marka", ref:"SMK m.6", es:["ün","şöhret"]},
  {k:"İtibar tazminatı", ara:["itibar tazminat"], anlam:"Tecavüz edenin ürünleri kötü üretmesi, kötü kullanması veya uygunsuz şekilde piyasaya sürmesi nedeniyle sınai mülkiyet hakkının itibarı zarar görürse ayrıca istenebilen tazminat (SMK m.150/2).", ornek:"Hakkın itibarı zarara uğrarsa itibar tazminatı da istenebilir.", kat:"Usul ve yaptırım", ref:"SMK m.150"},
  {k:"İttihat", ara:["ittihat"], anlam:"Birlik, birleşme. Paris Sözleşmesi'nin resmî adındaki 'milletlerarası bir ittihat', uluslararası birlik (Paris Birliği) demektir.", ornek:"Sözleşme, sınai mülkiyetin korunması için milletlerarası bir ittihat ihdas eder.", kat:"Eski Türkçe", ref:"SMK m.2", es:["birlik"]},
  {k:"İyiniyet", ara:["iyiniyet","iyi niyet"], anlam:"Bir hakkın kazanılmasına engel olan bir durumu bilmeme ve bilmesi de beklenemeyecek olma hâli (subjektif iyiniyet). Kanunun iyiniyete sonuç bağladığı hâllerde asıl olan iyiniyetin varlığıdır, aksini iddia eden ispat eder (TMK m.3).", ornek:"Sicile kaydedilmeyen hukuki işlemlerden doğan haklar iyiniyetli üçüncü kişilere karşı ileri sürülemez.", kat:"Genel hukuk", es:["hüsnüniyet"]},
  {k:"İyiniyetli üçüncü kişi", ara:["iyiniyetli üçüncü"], anlam:"Bir işlemin tarafı olmayan ve işlemdeki sakatlığı veya kayıt dışı bir hakkı bilmeyen, bilmesi de beklenemeyen kişi. Sicile kaydedilmemiş hukuki işlemlerden doğan haklar ona karşı ileri sürülemez (SMK m.148/5).", ornek:"Sicile kaydedilmeyen lisans, iyiniyetli üçüncü kişilere karşı ileri sürülemez.", kat:"Genel hukuk", ref:"SMK m.148"},
  {k:"Jenerik", ara:["jenerik"], anlam:"Bir ürün türünün genel/ortak adı hâline gelmiş ad. Marka, sahibinin eylem veya ihmali sonucu tescilli olduğu mallar için ticari çevrelerde ortak ad hâline gelirse iptal edilir; ilaçta 'jenerik ilaç' ise patent süresi bitmiş orijinal ilacın eşdeğeridir.", ornek:"Markanın sözlükte jenerik ad izlenimi verecek şekilde yayımlanması durumunda marka sahibi düzeltme isteyebilir.", kat:"Marka", ref:"SMK m.8", es:["cins adı","ortak ad"]},
  {k:"Kambiyo taahhüdü", ara:["kambiyo"], anlam:"Poliçe, bono veya çek gibi kambiyo senetlerine imza atarak borç altına girme. Vekilin bu işlemi yapabilmesi için özel olarak yetkilendirilmesi gerekir (TBK m.504/3).", ornek:"Dava açma, sulh, kambiyo taahhüdü ve bağışlama gibi işlemler için vekile özel yetki verilmelidir.", kat:"Genel hukuk", es:["senede dayalı borçlanma"]},
  {k:"Kamu düzeni", ara:["kamu düzen"], anlam:"Toplumun temel yapısını, güvenliğini ve esenliğini koruyan, kişilerin aksini kararlaştıramayacağı temel kurallar bütünü. Kamu düzenine aykırı işaretler marka olarak tescil edilmez, bu tür buluşlara patent verilmez.", ornek:"Kamu düzenine veya genel ahlaka aykırı işaretler marka olarak tescil edilmez.", kat:"Genel hukuk", ref:"SMK m.5"},
  {k:"Kamu yararı", ara:["kamu yararı"], anlam:"Kamu sağlığı veya millî güvenlik gibi toplumun genel çıkarına ilişkin gerekçeler. Bu nedenle Cumhurbaşkanınca zorunlu lisans verilmesine karar verilebilir (SMK m.132).", ornek:"Kamu yararı gerekçesiyle verilen zorunlu lisanslar inhisari olabilir.", kat:"Patent", ref:"SMK m.132", es:["kamu menfaati"]},
  {k:"Kamuya sunma", ara:["kamuya sun"], anlam:"Tasarımın sergilenmesi, satışa çıkarılması, yayımlanması gibi yollarla ilgili sektördeki çevrelerin makul olarak bilebileceği hâle gelmesi (SMK m.57). Tescilsiz tasarım koruması kamuya ilk sunulmayla başlar.", ornek:"Tescilsiz tasarımın koruma süresi kamuya ilk sunulduğu tarihten itibaren üç yıldır.", kat:"Tasarım", ref:"SMK m.57", es:["kamuya açıklama"]},
  {k:"Kanun Hükmünde Kararname", ara:["kanun hükmünde"], anlam:"Bakanlar Kurulunun yetki kanununa dayanarak çıkardığı kanun gücündeki düzenleme (KHK). SMK'dan önce marka, patent, tasarım ve coğrafi işaretler 551, 554, 555 ve 556 sayılı KHK'larla düzenleniyordu.", ornek:"Mülga 556 sayılı Kanun Hükmünde Kararname markaları düzenliyordu.", kat:"Genel hukuk", ref:"SMK m.191", es:["KHK"]},
  {k:"Karara itiraz", ara:["karara itiraz"], anlam:"Kurumun bir kararından etkilenen kişinin, kararın bildiriminden itibaren iki ay içinde Kuruma yaptığı itiraz; itirazları Kurul (YİDK) inceler (SMK m.20-21).", ornek:"Karara itiraz süresi kararın bildirim tarihinden itibaren iki aydır.", kat:"Usul ve yaptırım", ref:"SMK m.20"},
  {k:"Karıştırılma ihtimali", ara:["karıştırılma"], anlam:"Markaların ve kapsadıkları mal/hizmetlerin aynı veya benzer olması nedeniyle halkın iki markayı karıştırması ya da aralarında ekonomik bağ olduğunu düşünmesi tehlikesi; ilişkilendirilme ihtimalini de kapsar (SMK m.6/1).", ornek:"Halk tarafından karıştırılma ihtimali bulunan başvuru, itiraz üzerine reddedilir.", kat:"Marka", ref:"SMK m.6", es:["iltibas","karışıklık ihtimali"]},
  {k:"Karine", ara:["karine"], anlam:"Kanunun veya hayat tecrübesinin, bilinen bir olgudan bilinmeyen başka bir olgunun varlığını çıkarması; aksi ispatlanana kadar doğru kabul edilen varsayım.", ornek:"Mal veya hizmetlerin aynı sınıfta yer alması benzer olduklarına, farklı sınıflarda yer almaları da benzer olmadıklarına karine teşkil etmez.", kat:"Genel hukuk", ref:"SMK m.11", es:["yasal varsayım"]},
  {k:"Karşılıklılık ilkesi", ara:["karşılıklılık"], anlam:"Bir devletin, kendi vatandaşlarına koruma tanıyan başka bir devletin vatandaşlarına aynı korumayı tanıması. Türk vatandaşlarını koruyan devletlerin uyrukları SMK korumasından yararlanır (SMK m.3).", ornek:"Karşılıklılık ilkesi uyarınca yabancı ülke uyrukluları da korumadan yararlanır.", kat:"Uluslararası", ref:"SMK m.3", es:["mütekabiliyet"]},
  {k:"Kazai rüşt", ara:["kazai"], anlam:"Mahkeme kararıyla ergin kılınma. On beş yaşını dolduran küçük, kendi isteği ve velisinin rızasıyla mahkeme kararıyla ergin kılınabilir (TMK m.12).", ornek:"Kazai rüşt için küçüğün en az on beş yaşını doldurmuş olması gerekir.", kat:"Genel hukuk", es:["mahkeme kararıyla erginlik"]},
  {k:"Kazanılmış ayırt edicilik", ara:["kazanılmış ayırt","ayırt edici nitelik kazan"], anlam:"Başlangıçta ayırt edici olmayan bir işaretin, başvuru tarihinden önce yoğun kullanım sonucu tüketicinin gözünde belirli bir işletmeyle özdeşleşmesi. Bu durumda m.5/1'in (b), (c) ve (d) bentleri ret nedeni olmaz (SMK m.5/2).", ornek:"Bir marka başvuru tarihinden önce kullanılarak ayırt edici nitelik kazanmışsa tescili reddedilemez.", kat:"Marka", ref:"SMK m.5", es:["ikincil anlam","secondary meaning"]},
  {k:"Kesinleşme", ara:["kesinleş"], anlam:"Bir karara karşı kanun yollarına başvurma imkânının kalmaması (süre geçmesi veya üst mahkemenin onaması) ve kararın artık değiştirilemez hâle gelmesi.", ornek:"Hükümsüzlük kararının kesinleşmesinden sonra marka sicilden terkin edilir.", kat:"Usul ve yaptırım", ref:"SMK m.27"},
  {k:"Keşif", ara:["keşif","keşfi"], anlam:"Doğada zaten var olan bir şeyin bulunup ortaya çıkarılması. Keşifler, bilimsel teoriler ve matematiksel yöntemler buluş sayılmaz (SMK m.82/2-a).", ornek:"Yeni bir mineralin bulunması keşiftir, buluş değildir.", kat:"Patent", ref:"SMK m.82"},
  {k:"Kısıtlılık", ara:["kısıtlı"], anlam:"Ergin bir kişinin akıl hastalığı, savurganlık, bağımlılık, kötü yönetim, bir yıl veya daha uzun hapis cezası ya da kendi isteği gibi sebeplerle mahkeme kararıyla vesayet altına alınması. Kısıtlının fiil ehliyeti sınırlanır.", ornek:"Kısıtlı kişi, vasisinin rızası olmadan kendisini borç altına sokan işlemleri yapamaz.", kat:"Genel hukuk", es:["hacir"]},
  {k:"Kıyasen", ara:["kıyasen"], anlam:"Benzetme yoluyla; benzer bir durum için konmuş kuralın bu duruma da uygulanmasıyla.", ornek:"Hüküm bulunmayan hâllerde 121 inci madde hükmü kıyasen uygulanır.", kat:"Eski Türkçe", es:["benzetme yoluyla","kıyas yoluyla"]},
  {k:"Klonlama", ara:["klonlama"], anlam:"Bir canlının genetik olarak özdeş kopyasının üretilmesi. İnsan klonlama işlemleri patentlenemez (SMK m.82/3-d).", ornek:"İnsan klonlama işlemlerine patent verilmez.", kat:"Patent", ref:"SMK m.82", es:["kopyalama (genetik)"]},
  {k:"Koruma kapsamı", ara:["koruma kapsamı","korumanın kapsamı"], anlam:"Bir hakkın hangi ürün veya fiilleri kapsadığı. Patentte koruma kapsamı istemlerle belirlenir, tarifname ve resimler yorumda kullanılır (SMK m.89).", ornek:"Patent korumasının kapsamı istemlerle belirlenir.", kat:"Patent", ref:"SMK m.89"},
  {k:"Kötüniyet", ara:["kötüniyet","kötü niyet"], anlam:"Başkasının hakkını bildiği veya bilmesi gerektiği hâlde haksız yarar sağlamak ya da onu engellemek amacıyla hareket etme. Kötüniyetle yapılan marka başvuruları itiraz üzerine reddedilir ve hükümsüzlük nedenidir (SMK m.6/9).", ornek:"Kötüniyetle yapılan marka başvuruları itiraz üzerine reddedilir.", kat:"Marka", ref:"SMK m.6", es:["suiniyet"]},
  {k:"Kullanım ispatı", ara:["kullanım ispat"], anlam:"Beş yıldan uzun süredir tescilli bir markaya dayanarak itiraz veya dava açan kişiden, karşı tarafın talebiyle markasını son beş yılda ciddi biçimde kullandığını ya da kullanmamasının haklı nedeni olduğunu ispat etmesinin istenmesi (SMK m.19/2, m.25/7, m.29/2).", ornek:"Kullanım ispatlanamazsa itiraz, o mallar bakımından reddedilir.", kat:"Marka", ref:"SMK m.19", es:["kullanım kanıtı"]},
  {k:"Kullanma zorunluluğu", ara:["kullanma zorunlu","kullanılmama"], anlam:"Patent sahibinin buluşu kullanma yükümlülüğü. Patentin verilmesinin yayımından itibaren üç yıl veya başvurudan itibaren dört yıldan hangisi geç dolarsa, o tarihten sonra kullanılmama gerekçesiyle zorunlu lisans istenebilir (SMK m.130).", ornek:"Patent sahibi veya yetkili kıldığı kişi, patentle korunan buluşu kullanmak zorundadır.", kat:"Patent", ref:"SMK m.130"},
  {k:"Külfet", ara:["külfet"], anlam:"Yük, zahmet, masraf.", ornek:"Muhafazası ciddi külfet oluşturan suç eşyası hızlı imha prosedürüyle imha edilebilir.", kat:"Eski Türkçe", ref:"SMK m.163", es:["yük","zahmet"]},
  {k:"Lafız", ara:["lafzı","lafzın"], anlam:"Söz, kelime. Bir kuralın lafzı, metninin kelimesi kelimesine söylediğidir.", ornek:"Bu sonuç, iki fıkranın lafzından doğrudan çıkar.", kat:"Eski Türkçe", es:["metin","sözcük"]},
  {k:"Lahey Anlaşması", ara:["lahey"], anlam:"Endüstriyel tasarımların tek bir başvuruyla birçok ülkede uluslararası tescilini sağlayan WIPO sistemi.", ornek:"Lahey Anlaşması kapsamında tek başvuruyla birden fazla ülkede tasarım koruması istenebilir.", kat:"Uluslararası"},
  {k:"Lisans verme teklifi", ara:["lisans verme teklif"], anlam:"Patent sahibinin, buluşu kullanmak isteyen herkese lisans vereceğini Kuruma yazılı olarak bildirmesi; Bültende yayımlanır ve her zaman geri alınabilir (SMK m.128).", ornek:"Sicilde kayıtlı inhisari lisans varsa lisans verme teklifinde bulunulamaz.", kat:"Patent", ref:"SMK m.128"},
  {k:"Lokarno Anlaşması", ara:["lokarno","locarno"], anlam:"Endüstriyel tasarımların uluslararası sınıflandırmasını düzenleyen anlaşma.", ornek:"Tasarım başvurusundaki ürünler Lokarno sınıflandırmasına göre belirtilir.", kat:"Uluslararası", es:["Locarno"]},
  {k:"Lüzum", ara:["lüzum"], anlam:"Gereklilik, gerek.", ornek:"Mahkemeler, Adalet Bakanlığınca lüzum görülen yerlerde kurulur.", kat:"Eski Türkçe", ref:"SMK m.156", es:["gereklilik"]},
  {k:"Madrid Protokolü", ara:["madrid"], anlam:"Tek bir uluslararası marka başvurusuyla, menşe ofis üzerinden birden fazla ülkede marka koruması istenmesini sağlayan WIPO sistemi (SMK m.14).", ornek:"Madrid Protokolü kapsamında yapılan uluslararası marka başvuruları Kurum aracılığıyla yapılabilir.", kat:"Uluslararası", ref:"SMK m.14"},
  {k:"Mahiyet", ara:["mahiyet"], anlam:"Nitelik, bir şeyin iç yüzü, özü.", ornek:"Ticaret sırasında halkı yanıltıcı mahiyette olmayan kullanımlar engellenemez.", kat:"Eski Türkçe", es:["nitelik","öz"]},
  {k:"Mahreç işareti", ara:["mahreç"], anlam:"Belirli bir coğrafi alanla özdeşleşen ve üretim, işleme veya diğer işlemlerinden en az biri o alanın sınırları içinde yapılan ürünleri tanımlayan ad (SMK m.34/1-b). 'Mahreç' çıkış yeri demektir.", ornek:"Mahreç işaretinde üretim aşamalarından en az birinin belirlenen coğrafi alanda yapılması yeterlidir.", kat:"Coğrafi işaret", ref:"SMK m.34", es:["PGI","korunan coğrafi işaret"]},
  {k:"Mahsul", ara:["mahsul"], anlam:"Ürün, ortaya konan şey. 'Estetik niteliği bulunan mahsuller', sanatsal/estetik ürünler demektir ve buluş sayılmaz (SMK m.82/2-ç).", ornek:"Estetik niteliği bulunan mahsuller buluş niteliğinde sayılmaz.", kat:"Eski Türkçe", ref:"SMK m.82", es:["ürün"]},
  {k:"Mahsup", ara:["mahsup"], anlam:"Bir tutarı başka bir hesaptan düşme, hesaplaşma.", ornek:"Elkonulan ürünlerin değeri tazminattan mahsup edilir.", kat:"Eski Türkçe", es:["düşme","hesaptan indirme"]},
  {k:"Mahsus", ara:["mahsus"], anlam:"Özgü, ait, belirli bir şey için ayrılmış.", ornek:"Sınai Mülkiyetin Himayesine Mahsus Milletlerarası Bir İttihat.", kat:"Eski Türkçe", ref:"SMK m.2", es:["özgü","ait"]},
  {k:"Marka vekili", ara:["marka vekil"], anlam:"Marka, tasarım, coğrafi işaret ve geleneksel ürün adlarına ilişkin konularda hak sahiplerini Kurum nezdinde temsil eden, sicile kayıtlı kişi (SMK m.2/1-g).", ornek:"Yerleşim yeri yurt dışında olanlar Kurum nezdinde ancak marka veya patent vekiliyle işlem yapabilir.", kat:"Marka", ref:"SMK m.2"},
  {k:"Melezleme", ara:["melezleme"], anlam:"Farklı özellikteki iki bitki veya hayvanın çaprazlanarak yeni bir nesil elde edilmesi.", ornek:"Melezleme ya da seleksiyon gibi tamamen doğal bir olaydan oluşan üretim usulü patentlenemez.", kat:"Patent", ref:"SMK m.82", es:["çaprazlama","hibritleme"]},
  {k:"Menşe", ara:["menşe"], anlam:"Köken, kaynak, çıkış yeri.", ornek:"Garanti markası işletmelerin coğrafi menşelerini garanti etmeye yarayabilir.", kat:"Eski Türkçe", es:["köken","kaynak"]},
  {k:"Menşe adı", ara:["menşe adı"], anlam:"Tüm veya esas özelliklerini belirli bir coğrafi alana özgü doğal ve beşerî unsurlardan alan ve üretimi, işlenmesi ve diğer bütün işlemleri bu alanın sınırları içinde gerçekleşen ürünleri tanımlayan ad (SMK m.34/1-a).", ornek:"Menşe adında üretimin tüm aşamaları belirlenen coğrafi alanda gerçekleşmelidir.", kat:"Coğrafi işaret", ref:"SMK m.34", es:["PDO","korunan menşe adı"]},
  {k:"Menşe ofis", ara:["menşe ofis"], anlam:"Madrid sisteminde temel başvurunun veya tescilin bulunduğu ve uluslararası başvurunun sunulduğu ulusal/bölgesel ofis.", ornek:"Türkiye'deki temel başvuruya dayanan uluslararası başvuruda menşe ofis TÜRKPATENT'tir.", kat:"Uluslararası", es:["office of origin"]},
  {k:"Merci", ara:["merci"], anlam:"Başvurulacak yetkili makam, kurum.", ornek:"Yetkili mercilerce tescil izni verilmemiş armaları içeren işaretler tescil edilmez.", kat:"Eski Türkçe", ref:"SMK m.5", es:["makam","yetkili kurum"]},
  {k:"Merkezi saldırı", ara:["merkezi saldırı"], anlam:"Madrid sisteminde uluslararası tescilin, tescilden itibaren beş yıl içinde temel başvuru veya tescilin reddedilmesi, iptali ya da hükümsüzlüğü hâlinde bütün ülkelerde düşmesi.", ornek:"Merkezi saldırı sonrası düşen tescil, ulusal başvurulara dönüştürülebilir.", kat:"Uluslararası", es:["central attack"]},
  {k:"Mikrobiyolojik işlem", ara:["mikrobiyolojik"], anlam:"Mikrobiyolojik materyal içeren, onunla gerçekleştirilen veya sonucunda mikrobiyolojik materyal oluşan işlem. Bitki ve hayvan üretimine ilişkin yasaktan istisnadır; bu işlemler ve ürünleri patentlenebilir (SMK m.82/5).", ornek:"Mikrobiyolojik işlemler veya bu işlemler sonucu elde edilen ürünler patentlenebilir.", kat:"Patent", ref:"SMK m.82"},
  {k:"Muafiyet", ara:["muafiyet"], anlam:"Bir yükümlülükten bağışık tutulma, ayrık tutulma.", ornek:"Bir üyenin tanıdığı imtiyaz veya muafiyet diğer üyelerin vatandaşlarına da tanınır.", kat:"Eski Türkçe", es:["bağışıklık","istisna tutulma"]},
  {k:"Muhatap", ara:["muhatab"], anlam:"Kendisine bir söz, belge veya tebligat yöneltilen kişi.", ornek:"Elektronik tebligat, muhatabın posta kutusuna ilk giriş yaptığı tarihte yapılmış sayılır.", kat:"Usul ve yaptırım", ref:"SMK m.160", es:["alıcı","hitap edilen"]},
  {k:"Mutlak ret nedenleri", ara:["mutlak ret"], anlam:"İşaretin kendisinden kaynaklanan ve Kurumca kendiliğinden (re'sen) incelenen tescil engelleri; ör. ayırt edici olmama, tanımlayıcılık, halkı yanıltma, kamu düzenine aykırılık (SMK m.5).", ornek:"Kurum, başvuruyu mutlak ret nedenleri bakımından re'sen inceler.", kat:"Marka", ref:"SMK m.5"},
  {k:"Muvafakat", ara:["muvafakat"], anlam:"Onay, rıza, izin. Önceki marka sahibinin, kendi markasıyla aynı veya çok benzer bir markanın tescili için noter onaylı belgeyle verdiği izne 'muvafakatname' denir; bu durumda m.5/1-ç'ye göre ret yapılmaz (SMK m.5/3).", ornek:"Önceki marka sahibinin tescile açıkça muvafakat ettiğini gösteren noter onaylı belge Kuruma sunulabilir.", kat:"Marka", ref:"SMK m.5", es:["onay","rıza","izin"]},
  {k:"Müessese", ara:["müessese"], anlam:"Kuruluş, kurum; hukukta belirli kurallar bütünüyle oluşan hukuki kurum.", ornek:"Birlik ülkelerinden birinde işler durumda ticari müessesesi olan kişiler korumadan yararlanır.", kat:"Eski Türkçe", es:["kurum","kuruluş"]},
  {k:"Müeyyide", ara:["müeyyide"], anlam:"Yaptırım; kurala uyulmamasının hukuki sonucu.", ornek:"Teknik şartname, markanın şartnameye aykırı kullanılması hâlinde uygulanacak müeyyideleri belirler.", kat:"Eski Türkçe", es:["yaptırım"]},
  {k:"Mükerrer (bis/ter)", ara:["mükerrer"], anlam:"Tekrarlanan. Madde numaralarında aynı numaradan sonra eklenen maddeyi gösterir: '1 inci mükerrer 6 ncı madde' Paris Sözleşmesi m.6bis (tanınmış markalar), '2 nci mükerrer 6 ncı madde' ise m.6ter (devlet armaları, bayraklar ve resmî işaretler) demektir.", ornek:"Paris Sözleşmesinin 2 nci mükerrer 6 ncı maddesine göre reddedilecek işaretler tescil edilmez.", kat:"Uluslararası", ref:"SMK m.5", es:["bis","ter"]},
  {k:"Mülga", ara:["mülga"], anlam:"Yürürlükten kaldırılmış (kanun, kararname veya madde).", ornek:"Mülga 556 sayılı KHK dönemindeki kararlar.", kat:"Eski Türkçe", es:["yürürlükten kalkmış"]},
  {k:"Münhasıran", ara:["münhasır"], anlam:"Yalnızca, sadece, başka hiçbir şey olmaksızın. 'Münhasır' yalnız birine ait, ona özgü demektir.", ornek:"Tanımlayıcı işaretleri münhasıran içeren işaretler tescil edilmez.", kat:"Eski Türkçe", ref:"SMK m.5", es:["yalnızca","sadece","özgü"]},
  {k:"Müsadere", ara:["müsadere"], anlam:"Suçta kullanılan veya suçtan elde edilen eşyanın mahkeme kararıyla mülkiyetinin devlete geçirilmesi (TCK m.54-55).", ornek:"Suça konu eşyanın müsaderesine dair kesinleşmiş kararlar infaz edilir.", kat:"Usul ve yaptırım", ref:"SMK geçici m.3", es:["zoralım"]},
  {k:"Müstahzar", ara:["müstahzar"], anlam:"Hazırlanmış ürün, preparat; özellikle tıbbi veya kozmetik hazırlanmış madde.", ornek:"Sanayide ve bilimde kullanılan biyolojik müstahzarlar 1. sınıftadır.", kat:"Eski Türkçe", es:["preparat","hazırlanmış ürün"]},
  {k:"Müstehcen", ara:["müstehcen"], anlam:"Açık saçık, edep dışı, ahlak kurallarına aykırı.", ornek:"Müstehcen ifadeler içeren işaretler genel ahlaka aykırı sayılır.", kat:"Eski Türkçe", es:["edepsiz","açık saçık"]},
  {k:"Müteakip", ara:["müteakip"], anlam:"Ardından gelen, sonra.", ornek:"Belgenin posta kutusuna konulmasını müteakip muhatabın ilk giriş yaptığı tarihte tebligat yapılmış sayılır.", kat:"Eski Türkçe", ref:"SMK m.160", es:["ardından","sonra"]},
  {k:"Nakden", ara:["nakden"], anlam:"Peşin para olarak, nakit hâlinde.", ornek:"Önalım hakkı sahibi satış bedelini mahkemenin belirleyeceği yere nakden yatırır.", kat:"Eski Türkçe", ref:"SMK m.148", es:["nakit olarak","peşin"]},
  {k:"Nezdinde", ara:["nezdinde"], anlam:"Yanında, katında, önünde; bir makam veya kurum karşısında.", ornek:"Marka vekili, hak sahiplerini Kurum nezdinde temsil eder.", kat:"Eski Türkçe", ref:"SMK m.2", es:["huzurunda","katında"]},
  {k:"Nis Anlaşması", ara:["nis anlaşma"], anlam:"Marka başvurularında mal ve hizmetlerin uluslararası sınıflandırmasını (45 sınıf: 34 mal, 11 hizmet) düzenleyen anlaşma.", ornek:"Marka başvurusundaki mallar Nis Anlaşmasına göre sınıflandırılır.", kat:"Uluslararası", es:["Nice sınıflandırması"]},
  {k:"Nispi ret nedenleri", ara:["nispi ret","nispi"], anlam:"Başkasının önceki hakkından (önceki marka, tanınmış marka, ticaret unvanı, telif hakkı vb.) kaynaklanan ve yalnızca hak sahibinin itirazı üzerine incelenen tescil engelleri (SMK m.6).", ornek:"Nispi ret nedenleri ancak itiraz üzerine dikkate alınır.", kat:"Marka", ref:"SMK m.6", es:["göreli ret nedenleri"]},
  {k:"Olumsuz tespit davası", ara:["tecavüzün mevcut olmadığ","tecavüz teşkil etmediğ"], anlam:"Faaliyetinin bir sınai mülkiyet hakkına tecavüz oluşturmadığının tespitini isteyen kişinin hak sahibine karşı açtığı dava. Önce hak sahibinden görüş istenebilir; bir ay içinde cevap gelmez veya cevap kabul edilmezse dava açılır (SMK m.154).", ornek:"Kendisine karşı tecavüz davası açılmış kişi bu davayı açamaz.", kat:"Usul ve yaptırım", ref:"SMK m.154", es:["tecavüzün bulunmadığının tespiti davası"]},
  {k:"Ortak marka", ara:["ortak marka"], anlam:"Üretim, ticaret veya hizmet işletmelerinden oluşan bir grup tarafından kullanılan ve gruptaki işletmelerin mal veya hizmetlerini diğer işletmelerinkinden ayırt etmeye yarayan işaret (SMK m.31).", ornek:"Bir üretici birliği, üyelerinin kullanması için ortak marka tescil ettirebilir.", kat:"Marka", ref:"SMK m.31", es:["kolektif marka"]},
  {k:"Ortalama tüketici", ara:["ortalama tüketici"], anlam:"Makul ölçüde bilgili, dikkatli ve özenli kabul edilen tipik alıcı; karıştırılma ihtimali ve ayırt edicilik onun algısına göre değerlendirilir.", ornek:"İlaçlar gibi özenle satın alınan ürünlerde ortalama tüketicinin dikkat düzeyi daha yüksektir.", kat:"Marka"},
  {k:"Önalım hakkı", ara:["önalım"], anlam:"Bir pay veya hak üçüncü kişiye satıldığında, onu aynı şartlarla öncelikle satın alabilme hakkı. Sınai mülkiyet hakkının paydaşları ile işverenin iflasında çalışan bu haktan yararlanır (SMK m.148/3, m.120).", ornek:"Cebri artırmayla satışlarda önalım hakkı kullanılamaz.", kat:"Genel hukuk", ref:"SMK m.148", es:["şufa hakkı"]},
  {k:"Önceki kullanım hakkı", ara:["önceki kullanım"], anlam:"Başvuru tarihinden önce buluşu (veya tasarımı) Türkiye'de iyiniyetle kullanan ya da kullanmak için ciddi hazırlık yapan kişinin, sonradan verilen hakka rağmen bu kullanımı işletmesinin makul ihtiyaçları ölçüsünde sürdürebilme hakkı (SMK m.87, m.60).", ornek:"Önceki kullanımdan doğan hak, işletmeyle birlikte devredilebilir.", kat:"Patent", ref:"SMK m.87", es:["önkullanım hakkı"]},
  {k:"Övücü terim", ara:["övücü"], anlam:"Malın veya hizmetin kalitesini öven genel reklam ifadeleri (ör. 'süper', 'en iyi'); kural olarak ayırt edici değildir.", ornek:"'Premium' gibi övücü terimler tek başına marka olarak tescil edilemez.", kat:"Marka", es:["laudatory terim","methiye ifadesi"]},
  {k:"Paris Sözleşmesi", ara:["paris sözleşme"], anlam:"Sınai mülkiyetin korunmasına ilişkin 1883 tarihli temel uluslararası sözleşme; ulusal muamele ve rüçhan hakkı ilkelerini getirir. SMK'daki resmî adı 'Sınai Mülkiyetin Himayesine Mahsus Milletlerarası Bir İttihat İhdas Edilmesine Dair Sözleşme'dir (SMK m.2/1-ğ).", ornek:"Paris Sözleşmesine taraf ülkelerde yapılan ilk başvurular rüçhan hakkı doğurur.", kat:"Uluslararası", ref:"SMK m.2"},
  {k:"Patent isteme hakkı", ara:["patent isteme hakkı"], anlam:"Bir buluş için patent başvurusu yapabilme hakkı; buluşu yapana veya halefine aittir, birlikte yapılan buluşlarda ortaklaşa aittir (SMK m.109).", ornek:"Patent isteme hakkı buluşu yapana veya halefine aittir.", kat:"Patent", ref:"SMK m.109"},
  {k:"Patent vekili", ara:["patent vekil"], anlam:"Patent, faydalı model ve tasarım haklarına ilişkin konularda hak sahiplerini Kurum nezdinde temsil eden, sicile kayıtlı kişi (SMK m.2/1-h).", ornek:"Patent vekili tayin edilmişse tüm işlemler vekil tarafından yapılır.", kat:"Patent", ref:"SMK m.2"},
  {k:"PCT", ara:["patent işbirliği"], anlam:"Patent İşbirliği Antlaşması; tek bir uluslararası başvuruyla çok sayıda ülkede başvuru etkisi doğuran sistem. Patenti WIPO vermez; her ülke ulusal aşamada kendisi karar verir.", ornek:"PCT başvurusu, uluslararası araştırma raporu ve yazılı görüşle devam eder.", kat:"Uluslararası", es:["Patent İşbirliği Antlaşması"]},
  {k:"Re'sen", ara:["re'sen","resen"], anlam:"Kendiliğinden; bir tarafın talebi olmaksızın makamın kendi görevi gereği.", ornek:"Hükümsüzlük kararının kesinleşmesinden sonra mahkeme bu kararı Kuruma resen gönderir.", kat:"Usul ve yaptırım", ref:"SMK m.27", es:["kendiliğinden","ex officio"]},
  {k:"Rehin", ara:["rehin"], anlam:"Bir alacağı güvenceye almak için bir mal veya hak üzerinde kurulan, borç ödenmezse onun paraya çevrilmesini sağlayan hak. Sınai mülkiyet hakları rehin verilebilir (SMK m.148).", ornek:"Sınai mülkiyet hakkı devredilebilir, lisans konusu olabilir, rehin verilebilir.", kat:"Genel hukuk", ref:"SMK m.148"},
  {k:"Rüçhan belgesi", ara:["rüçhan belge"], anlam:"Rüçhan hakkına dayanak olan ilk başvurunun yapıldığı ofisten alınan, başvurunun tarihini ve içeriğini gösteren onaylı belge; süresi içinde Kuruma sunulmalıdır.", ornek:"Rüçhan belgesi süresinde sunulmazsa rüçhan hakkı talebi geçersiz sayılır.", kat:"Uluslararası", es:["öncelik belgesi"]},
  {k:"Rüçhan hakkı", ara:["rüçhan"], anlam:"Öncelik hakkı: Paris Sözleşmesi veya DTÖ üyesi bir ülkede usulüne uygun ilk başvuruyu yapan kişinin, belirli süre içinde (marka ve tasarım için 6 ay, patent ve faydalı model için 12 ay) Türkiye'de aynı konuda yaptığı başvuruda ilk başvurunun tarihinden yararlanması (SMK m.12, m.62, m.93).", ornek:"Rüçhan hakkı talep edilen başvuruda, rüçhan tarihi başvuru tarihi olarak kabul edilir.", kat:"Uluslararası", ref:"SMK m.12", es:["öncelik hakkı","priority"]},
  {k:"Sanayiye uygulanabilirlik", ara:["sanayiye uygulanabil"], anlam:"Buluşun tarım dâhil herhangi bir sanayi dalında üretilebilmesi veya kullanılabilmesi; patent ve faydalı model için aranır (SMK m.83).", ornek:"Yeni olan ve sanayiye uygulanabilen buluşlar faydalı model ile korunur.", kat:"Patent", ref:"SMK m.83"},
  {k:"Satışa arz", ara:["satışa arz","arz eden"], anlam:"Satışa sunma, satış için ortaya koyma.", ornek:"Taklit malı satışa arz eden veya satan kişi cezalandırılır.", kat:"Eski Türkçe", ref:"SMK m.30", es:["satışa sunma"]},
  {k:"Seçenek özgürlüğü", ara:["seçenek özgürlüğü","tasarımcının"], anlam:"Tasarımcının bir ürünü tasarlarken sahip olduğu serbestlik alanı; teknik zorunluluklar bu alanı daraltır. Ayırt edicilik değerlendirilirken dikkate alınır (SMK m.56/6).", ornek:"Ayırt edici niteliğin değerlendirilmesinde tasarımcının seçenek özgürlüğünün derecesi dikkate alınır.", kat:"Tasarım", ref:"SMK m.56", es:["tasarım serbestisi"]},
  {k:"Sehven", ara:["sehven"], anlam:"Yanlışlıkla, dikkatsizlik sonucu.", ornek:"Bir marka, yayıma itiraz aşaması tamamlanmadan sehven tescil edilmiştir.", kat:"Eski Türkçe", es:["yanlışlıkla","sehiv sonucu"]},
  {k:"Seleksiyon", ara:["seleksiyon"], anlam:"İstenen özelliklere sahip bitki veya hayvanların seçilerek üretilmesi.", ornek:"Seleksiyonla yeni bir buğday türü elde etme yöntemi esas olarak biyolojik işlemdir.", kat:"Patent", ref:"SMK m.82", es:["seçilim","ayıklama"]},
  {k:"Serbest buluş", ara:["serbest buluş"], anlam:"Çalışanın yaptığı ancak hizmet buluşu niteliği taşımayan buluş; hak çalışana aittir, fakat çalışan işverene bildirim yapmakla yükümlüdür (SMK m.113, m.119).", ornek:"Yükseköğretim kurumu süresinde patent başvurusu yapmazsa buluş serbest buluş niteliği kazanır.", kat:"Patent", ref:"SMK m.119"},
  {k:"Seri marka", ara:["seri marka","serinin"], anlam:"Aynı esas unsuru paylaşan ve tüketicide bir 'marka ailesi' algısı yaratan markalar. Seri markaya dayanan itirazda, serinin piyasada fiilen kullanıldığı gösterilmelidir.", ornek:"İtiraz sahibi, serinin yalnızca tescilli değil piyasada fiilen kullanılan markalardan oluştuğunu göstermelidir.", kat:"Marka", es:["marka ailesi"]},
  {k:"Sessiz kalma", ara:["sessiz kal"], anlam:"Önceki hak sahibinin, sonraki markanın kullanıldığını bildiği veya bilmesi gerektiği hâlde beş yıl boyunca buna ses çıkarmaması. Sonraki marka kötüniyetli değilse artık hükümsüzlük talep edemez (SMK m.25/6).", ornek:"Önceki marka sahibi beş yıl boyunca sessiz kalmışsa sonraki markanın hükümsüzlüğünü isteyemez.", kat:"Marka", ref:"SMK m.25", es:["hakkın sessiz kalmayla kaybı"]},
  {k:"Sınai mülkiyet hakkı", ara:["sınai mülkiyet"], anlam:"Marka, coğrafi işaret, tasarım, patent ve faydalı model üzerindeki haklar (SMK m.2/1-ı). 'Sınai', sanayiye ilişkin demektir.", ornek:"Sınai mülkiyet hakkı devredilebilir, miras yoluyla intikal edebilir ve lisans konusu olabilir.", kat:"Genel hukuk", ref:"SMK m.2", es:["endüstriyel mülkiyet hakkı"]},
  {k:"Sınırlı ehliyetsiz", ara:["sınırlı ehliyetsiz"], anlam:"Ayırt etme gücüne sahip küçükler ve kısıtlılar. Kendi işlemleriyle borç altına girmeleri için kural olarak yasal temsilcinin rızası gerekir; karşılıksız kazanma ve kişiye sıkı sıkıya bağlı hakları kullanma işlemlerini tek başına yapabilirler (TMK m.16).", ornek:"Sınırlı ehliyetsiz, bağış kabul etmek gibi karşılıksız kazanmalar için yasal temsilcisinin rızasına muhtaç değildir.", kat:"Genel hukuk"},
  {k:"Sicilde gösterilebilirlik", ara:["sicilde gösteril"], anlam:"Bir işaretin marka olabilmesi için korumanın konusunun açık ve kesin anlaşılacağı şekilde sicilde gösterilebilmesi şartı. SMK, eski mevzuattaki 'grafiksel gösterim' şartını aramaz.", ornek:"Ses de sicilde gösterilebilir olduğu sürece marka olabilir.", kat:"Marka", ref:"SMK m.4"},
  {k:"Soruşturma ve kovuşturma", ara:["soruştur","kovuştur"], anlam:"Ceza yargılamasının iki evresi: soruşturma, suç şüphesinin öğrenilmesinden iddianamenin kabulüne kadar savcılık aşamasıdır; kovuşturma, iddianamenin kabulünden hükmün kesinleşmesine kadar mahkeme aşamasıdır (CMK m.2).", ornek:"Bu maddede yer alan suçların soruşturulması ve kovuşturulması şikâyete bağlıdır.", kat:"Usul ve yaptırım", ref:"SMK m.30"},
  {k:"Strazburg Anlaşması", ara:["strazburg","uluslararası patent sınıflandırma"], anlam:"Uluslararası Patent Sınıflandırmasını (IPC) düzenleyen anlaşma.", ornek:"Strazburg Anlaşması patentlerin uluslararası sınıflandırmasına (IPC) ilişkindir.", kat:"Uluslararası", es:["IPC","Strasbourg"]},
  {k:"Suretiyle", ara:["suretiyle","suretle"], anlam:"Yoluyla, biçiminde, şeklinde. 'Sureti' ise bir belgenin kopyası anlamına da gelir.", ornek:"Başkasına ait marka hakkına iltibas suretiyle tecavüz eden kişi cezalandırılır.", kat:"Eski Türkçe", ref:"SMK m.30", es:["yoluyla","biçiminde"]},
  {k:"Süje", ara:["süjeye"], anlam:"Hukukta hakkın sahibi olan kişi, özne. Karşıtı 'obje', yani hakkın konusu olan şeydir.", ornek:"Ticaret unvanı tacire (süjeye), işletme adı işletmeye (objeye) ilişkindir.", kat:"Genel hukuk", es:["hak sahibi","özne"]},
  {k:"Şikâyet", ara:["şikâyet"], anlam:"Ceza hukukunda suçtan zarar görenin, failin cezalandırılması için yetkili makama başvurması. Marka hakkına tecavüz suçlarının soruşturulması ve kovuşturulması şikâyete bağlıdır (SMK m.30/6).", ornek:"SMK m.30'daki suçların soruşturulması ve kovuşturulması şikâyete bağlıdır.", kat:"Usul ve yaptırım", ref:"SMK m.30"},
  {k:"Tahsis", ara:["tahsis"], anlam:"Bir şeyi belirli bir amaç veya kişi için ayırma, özgüleme.", ornek:"Tebligat, Kurum tarafından kişi için tahsis edilen elektronik posta kutusuna konulur.", kat:"Eski Türkçe", ref:"SMK m.160", es:["ayırma","özgüleme"]},
  {k:"Tanımlayıcı işaret", ara:["tanımlayıcı"], anlam:"Malın veya hizmetin cinsini, çeşidini, kalitesini, miktarını, amacını, değerini, coğrafi kaynağını veya üretim zamanını doğrudan anlatan işaret. Münhasıran veya esas unsur olarak bunlardan oluşan işaretler tescil edilmez (SMK m.5/1-c).", ornek:"'Taze' kelimesi süt ürünleri için tanımlayıcı bir işarettir.", kat:"Marka", ref:"SMK m.5"},
  {k:"Tanınmış marka", ara:["tanınmış"], anlam:"Paris Sözleşmesi m.6bis anlamında ilgili ticari çevrelerde yaygın olarak bilinen marka; Türkiye'de tescilli olmasa da aynı veya benzer mallar için yapılan başvurulara itiraz edilebilir (SMK m.6/4).", ornek:"Türkiye'de tanınmış markayla aynı veya benzer olan başvuru, itiraz üzerine reddedilir.", kat:"Marka", ref:"SMK m.6", es:["meşhur marka","well-known mark"]},
  {k:"Tanzim", ara:["tanzim"], anlam:"Düzenleme; bir belgeyi, tutanağı hazırlama.", ornek:"İmha işlemine ilişkin tutanak tanzim olunur.", kat:"Eski Türkçe", es:["düzenleme"]},
  {k:"Tarifname", ara:["tarifname"], anlam:"Patent başvurusunda buluşu, ilgili alandaki uzmanın uygulayabileceği açıklık ve tamlıkta anlatan teknik belge; istemler, özet ve resimlerle birlikte verilir (SMK m.92).", ornek:"Buluş, tarifnamede ilgili alandaki uzmanın uygulayabileceği şekilde açıklanmalıdır.", kat:"Patent", ref:"SMK m.92", es:["açıklama metni","description"]},
  {k:"Tasarruf", ara:["tasarruf"], anlam:"Hukukta, bir hak üzerinde doğrudan etki doğuran işlem: hakkı devretme, sınırlama (lisans, rehin), değiştirme veya ortadan kaldırma. Tasarruf yetkisi, bu işlemleri yapabilme yetkisidir.", ornek:"Yetkisi olmadığı hâlde başkasına ait marka hakkı üzerinde devir, lisans veya rehin yoluyla tasarrufta bulunan kişi cezalandırılır.", kat:"Genel hukuk", ref:"SMK m.30"},
  {k:"Tasdik", ara:["tasdik"], anlam:"Onaylama, doğrulama.", ornek:"Sergide teşhir eden kişi, markanın tasdikli örneğini ibraz etmelidir.", kat:"Eski Türkçe", es:["onay","onaylama"]},
  {k:"Teamül", ara:["teamül"], anlam:"Bir çevrede uzun süredir uygulanan ve uyulması beklenen yerleşik alışkanlık. Vekâlet sözleşmesinde ücret kararlaştırılmamış olsa da teamül varsa vekil ücrete hak kazanır (TBK m.502).", ornek:"Sözleşmede kararlaştırılmışsa veya teamül varsa vekil ücrete hak kazanır.", kat:"Genel hukuk", es:["örf","yerleşik uygulama"]},
  {k:"Tebellüğ", ara:["tebellüğ"], anlam:"Tebliğ edilen belgeyi resmen alma; belgenin muhataba ulaştığı an.", ornek:"İşveren, çalışanın bildirimine tebellüğ tarihinden itibaren iki ay içinde cevap vermelidir.", kat:"Usul ve yaptırım", ref:"SMK m.115", es:["tebliğ alma"]},
  {k:"Tebligat", ara:["tebligat","tebliğ"], anlam:"Bir belgenin veya kararın ilgilisine kanuna uygun şekilde resmen bildirilmesi; süreler kural olarak tebliğden itibaren işler. Kurum tebligatları onay alınarak elektronik posta kutusuna da yapılabilir (SMK m.160).", ornek:"Elektronik tebligat, belgenin posta kutusuna konulduğu tarihi izleyen onuncu günün sonunda yapılmış sayılır.", kat:"Usul ve yaptırım", ref:"SMK m.160", es:["resmî bildirim"]},
  {k:"Tecavüz", ara:["tecavüz"], anlam:"Sınai mülkiyet hukukunda, hak sahibinin izni olmadan korunan hakkın kapsamına giren fiillerin (üretme, satma, ithal etme, kullanma vb.) yapılması; hakkın ihlali anlamına gelir, cinsel bir anlamı yoktur (SMK m.29, m.81, m.141).", ornek:"Marka sahibinin izni olmaksızın markanın kullanılması marka hakkına tecavüz sayılır.", kat:"Usul ve yaptırım", ref:"SMK m.29", es:["ihlal","hak ihlali"]},
  {k:"Tecavüzün önlenmesi ve durdurulması", ara:["muhtemel tecavüz","durdurulması"], anlam:"Hak sahibinin mahkemeden muhtemel tecavüzün önlenmesini (men), süren tecavüzün durdurulmasını ve sonuçlarının giderilmesini (ref) talep etmesi (SMK m.149).", ornek:"Hak sahibi, tecavüz fiillerinin önlenmesini ve durdurulmasını mahkemeden isteyebilir.", kat:"Usul ve yaptırım", ref:"SMK m.149", es:["men'i müdahale","tecavüzün men'i ve ref'i"]},
  {k:"Tedavi ve teşhis yöntemleri", ara:["teşhis","cerrahi"], anlam:"İnsan veya hayvan vücuduna uygulanan teşhis yöntemleri ile cerrahi yöntemler dâhil tüm tedavi yöntemleri patentlenemez; ancak bu yöntemlerde kullanılan ürünler, madde ve terkipler patentlenebilir (SMK m.82/3-c, m.82/6).", ornek:"Yeni bir ameliyat tekniği patentlenemez, ama bu ameliyatta kullanılan cihaz patentlenebilir.", kat:"Patent", ref:"SMK m.82"},
  {k:"Tekabül", ara:["tekabül"], anlam:"Karşılık gelme, denk düşme.", ornek:"Yıllık ücretin vade tarihi, başvuru tarihine tekabül eden ay ve gündür.", kat:"Eski Türkçe", ref:"SMK m.101", es:["karşılık gelme","denk düşme"]},
  {k:"Tekel", ara:["tekel"], anlam:"Bir mal veya hizmetin üretim ya da satışının yalnızca bir kişiye veya kuruluşa ait olması. SMK'daki 'kanuni tekel', bir faaliyetin kanunla devlete veya bir kuruluşa ayrılmasıdır; bu alandaki buluşların kullanımı tekel sahibinin iznine bağlıdır (SMK m.88).", ornek:"Kanuni tekel konusu faaliyetlerle ilgili buluşların kullanılması tekel sahibinin iznine bağlıdır.", kat:"Genel hukuk", ref:"SMK m.88", es:["inhisar","monopol"]},
  {k:"Tekniğin bilinen durumu", ara:["tekniğin bilinen durum"], anlam:"Başvuru (veya rüçhan) tarihinden önce dünyanın herhangi bir yerinde yazılı veya sözlü tarifname, kullanım ya da başka bir yolla kamuya erişilebilir hâle gelmiş her şey. Yenilik ve buluş basamağı buna göre değerlendirilir (SMK m.83).", ornek:"Buluş, tekniğin bilinen durumuna dâhil değilse yeni kabul edilir.", kat:"Patent", ref:"SMK m.83", es:["önceki teknik","prior art"]},
  {k:"Teknik şartname", ara:["teknik şartname","şartname"], anlam:"Garanti veya ortak markanın kimler tarafından, hangi şartlarla kullanılacağını, denetim usulünü ve yaptırımları gösteren belge; başvuruyla birlikte verilir (SMK m.32).", ornek:"Ortak markanın teknik şartnameye aykırı kullanılması iptal nedenidir.", kat:"Marka", ref:"SMK m.32"},
  {k:"Temsil", ara:["temsil"], anlam:"Bir kişinin (temsilci) başkası (temsil olunan) adına ve hesabına hukuki işlem yapması; işlemin sonuçları doğrudan temsil olunanı bağlar.", ornek:"Marka vekili, hak sahiplerini Kurum nezdinde temsil eder.", kat:"Genel hukuk"},
  {k:"Terkin", ara:["terkin"], anlam:"Bir kaydın sicilden silinmesi.", ornek:"Hükümsüzlük veya iptal kararının kesinleşmesinden sonra marka sicilden terkin edilir.", kat:"Usul ve yaptırım", ref:"SMK m.27", es:["silme","kayıttan düşme"]},
  {k:"Terkip", ara:["terkip"], anlam:"Bileşim, karışım. Tedavi yöntemleri patentlenemese de bu yöntemlerde kullanılan madde ve terkipler patentlenebilir (SMK m.82/6).", ornek:"Tedavi yöntemi patentlenemez ama o yöntemde kullanılan ilaç terkibi patentlenebilir.", kat:"Eski Türkçe", ref:"SMK m.82", es:["bileşim","formülasyon"]},
  {k:"Tertip", ara:["tertip"], anlam:"Düzen, sıra; Düstur'da kanunların yayın dizisi.", ornek:"Kanun, Düstur'un beşinci tertibinde yayımlanmıştır.", kat:"Eski Türkçe", es:["dizi","düzen"]},
  {k:"Tesadüfi", ara:["tesadüfi"], anlam:"Rastlantısal; arada bir, plansız olarak meydana gelen.", ornek:"Taşıt araçlarının geçici veya tesadüfi olarak Türkiye'de bulunması hâlinde patentli buluşun kullanımı tecavüz sayılmaz.", kat:"Eski Türkçe", ref:"SMK m.85", es:["rastlantısal","arızi"]},
  {k:"Tescil ettiren", ara:["tescil ettiren"], anlam:"Coğrafi işaret veya geleneksel ürün adı başvurusunu yaparak tescili sağlayan üretici grubu, kamu kurumu, meslek kuruluşu gibi kişi veya kuruluş.", ornek:"Coğrafi işarete tecavüz nedeniyle açılan dava tescil ettirene ihbar olunur.", kat:"Coğrafi işaret", ref:"SMK m.43"},
  {k:"Tescilsiz tasarım", ara:["tescilsiz tasarım"], anlam:"Tescil edilmeksizin, Türkiye'de ilk kez kamuya sunulmasıyla korunan tasarım; koruma üç yıl sürer ve yalnızca kopyalamaya karşıdır (SMK m.59, m.69).", ornek:"Tescilsiz tasarımlar yalnızca kopyalama yoluyla kullanıma karşı korunur.", kat:"Tasarım", ref:"SMK m.69"},
  {k:"Teşebbüs", ara:["teşebbüs"], anlam:"Ekonomik faaliyette bulunan işletme, girişim. Marka, bir teşebbüsün mal veya hizmetlerini diğer teşebbüslerinkinden ayırt etmeye yarar (SMK m.4).", ornek:"Marka, bir teşebbüsün mallarının veya hizmetlerinin diğer teşebbüslerin mallarından ayırt edilmesini sağlar.", kat:"Marka", ref:"SMK m.4", es:["işletme","girişim"]},
  {k:"Teşhir", ara:["teşhir"], anlam:"Sergileme, gözler önüne serme.", ornek:"Uluslararası sergilerde markayla birlikte teşhir eden kişi, teşhir tarihinden itibaren rüçhan hakkından yararlanabilir.", kat:"Eski Türkçe", es:["sergileme"]},
  {k:"Tevdi (biyolojik materyal)", ara:["tevdi","mikroorganizma"], anlam:"Tevdi: teslim etme, emanet bırakma. Buluş tarifnamede yeterince açıklanamayan bir biyolojik materyal veya mikroorganizma içeriyorsa, bir örneğinin yetkili tevdi kuruluşuna bırakılmasıdır (SMK m.92).", ornek:"Mikroorganizma örneği, başvuru tarihinden önce yetkili bir kuruluşa tevdi edilmelidir.", kat:"Patent", ref:"SMK m.92", es:["depolama","emanet etme"]},
  {k:"Ticaret unvanı", ara:["ticaret unvan"], anlam:"Tacirin ticari işletmesine ilişkin işlemleri yaparken kullandığı ve imza olarak attığı ad; kişiye (tacire) ilişkindir. Başkasına ait ticaret unvanını içeren marka başvurusu, hak sahibinin itirazı üzerine reddedilir (SMK m.6/6).", ornek:"Ticaret unvanı tacire (süjeye), işletme adı ise işletmeye (objeye) ilişkin bir addır.", kat:"Genel hukuk", ref:"SMK m.6"},
  {k:"Ticari vekil veya temsilci", ara:["ticari vekil"], anlam:"Bir işletme adına sürekli olarak iş gören yardımcı; marka hukukunda yabancı marka sahibinin distribütörü, acentesi gibi kişiler. Marka sahibinin izni olmadan bunlar adına tescil edilen markanın devri veya hükümsüzlüğü istenebilir (SMK m.10).", ornek:"Marka, sahibinin izni olmaksızın ticari vekil adına tescil edilirse marka sahibi kendi adına devrini isteyebilir.", kat:"Marka", ref:"SMK m.10", es:["ajan","temsilci"]},
  {k:"Topografya (entegre devre)", ara:["topoğrafya","topografya","entegre devre"], anlam:"Entegre devrelerin (yarı iletken çiplerin) katmanlarının üç boyutlu yerleşim tasarımı; SMK dışında 5147 sayılı Kanunla korunur.", ornek:"Entegre devre topografyaları ayrı bir kanunla korunur.", kat:"Patent", es:["yerleşim tasarımı","mask work"]},
  {k:"TRIPS", ara:["trıps"], anlam:"Dünya Ticaret Örgütü'nün Ticaretle Bağlantılı Fikrî Mülkiyet Hakları Anlaşması; tüm DTÖ üyeleri için asgari koruma standartları, ulusal muamele ve en çok kayrılan ulus ilkelerini düzenler.", ornek:"TRIPS'e göre patent koruma süresi başvuru tarihinden itibaren en az yirmi yıldır.", kat:"Uluslararası", es:["Ticaretle Bağlantılı Fikrî Mülkiyet Hakları Anlaşması"]},
  {k:"Ulusal aşama", ara:["ulusal aşama"], anlam:"PCT başvurusunun uluslararası evreden sonra, koruma istenen her ülkenin ofisinde incelenmeye başladığı evre; kural olarak rüçhan tarihinden itibaren 30 ay içinde girilir.", ornek:"PCT başvurusu Türkiye'de ulusal aşamaya girdiğinde Kurum incelemeyi yapar.", kat:"Uluslararası", es:["national phase"]},
  {k:"Ulusal muamele", ara:["ulusal muamele"], anlam:"Bir anlaşmaya taraf devletin, diğer taraf devletlerin vatandaşlarına kendi vatandaşlarına tanıdığı korumayı aynen tanıması ilkesi (Paris m.2, TRIPS m.3).", ornek:"Ulusal muamele ilkesine göre yabancı başvuru sahibi Türk vatandaşıyla aynı korumadan yararlanır.", kat:"Uluslararası", es:["millî muamele","national treatment"]},
  {k:"Uluslararası araştırma raporu", ara:["uluslararası araştırma"], anlam:"PCT başvurusunda Uluslararası Araştırma Otoritesinin hazırladığı, ilgili tekniğin bilinen durumu belgelerini gösteren rapor; yazılı görüşle birlikte düzenlenir.", ornek:"Uluslararası araştırma raporu, başvuru sahibine ulusal aşamadan önce fikir verir.", kat:"Uluslararası", es:["ISR"]},
  {k:"Uluslararası ön inceleme", ara:["uluslararası ön inceleme"], anlam:"PCT'de başvuru sahibinin isteğe bağlı olarak talep ettiği, buluşun yenilik, buluş basamağı ve sanayiye uygulanabilirlik bakımından bağlayıcı olmayan ön değerlendirmesi (PCT Bölüm II).", ornek:"Uluslararası ön inceleme raporu ulusal ofisleri bağlamaz.", kat:"Uluslararası", es:["IPRP","PCT Bölüm II"]},
  {k:"Usul patenti", ara:["usul patent"], anlam:"Bir ürünü elde etme veya bir işi yapma yöntemine verilen patent. Koruma, bu usulle doğrudan elde edilen ürünleri de kapsar (SMK m.85/2-ç).", ornek:"Patent konusu usulle doğrudan elde edilen ürünlerin izinsiz satışı tecavüzdür.", kat:"Patent", ref:"SMK m.85", es:["yöntem patenti","process patent"]},
  {k:"Uzman kişi (patent)", ara:["uzmana göre","uzman kişi","alandaki uzman"], anlam:"Buluş basamağı ve yeterli açıklama değerlendirilirken esas alınan, ilgili teknik alanda ortalama bilgi ve beceriye sahip varsayımsal kişi.", ornek:"Tarifname, buluşu ilgili alandaki uzmanın uygulayabileceği açıklıkta olmalıdır.", kat:"Patent", es:["tekniğin uzmanı","person skilled in the art"]},
  {k:"Üçüncü kişi görüşleri", ara:["üçüncü kişi görüş","üçüncü kişilerin görüş"], anlam:"Herkesin, yayımlanan bir marka başvurusunun m.5/1 (ç) bendi dışındaki mutlak ret nedenleri kapsamında olduğunu tescile kadar Kuruma yazılı ve gerekçeli bildirebilmesi; görüş bildiren kişi işlemlere taraf olmaz (SMK m.17).", ornek:"Üçüncü kişiler, başvurunun tanımlayıcı olduğuna ilişkin görüşlerini markanın tesciline kadar Kuruma sunabilir.", kat:"Marka", ref:"SMK m.17"},
  {k:"Validasyon", ara:["validasyon"], anlam:"Verilen bir Avrupa patentinin belirli bir ülkede geçerli kılınması işlemi; Türkiye için çeviri sunulur ve ücret ödenir.", ornek:"Avrupa patentinin validasyonu yapılmazsa patent Türkiye'de hüküm doğurmaz.", kat:"Uluslararası", es:["geçerli kılma"]},
  {k:"Vekâlet sözleşmesi", ara:["vekâlet","vekalet"], anlam:"Vekilin, vekâlet verenin bir işini görmeyi veya bir işlemini yapmayı üstlendiği sözleşme (TBK m.502). Vekâletname ise vekile verilen yetkiyi gösteren belgedir.", ornek:"Kurum, vekilin yetkisini gösteren vekâletnamenin aslını veya onaylı suretini isteyebilir.", kat:"Genel hukuk", ref:"SMK m.160"},
  {k:"Viyana Anlaşması", ara:["viyana"], anlam:"Markaların şekil (figüratif) unsurlarının uluslararası sınıflandırmasını düzenleyen anlaşma.", ornek:"Şekil markalarının görsel unsurları Viyana sınıflandırmasına göre kodlanır.", kat:"Uluslararası"},
  {k:"WIPO", ara:["dünya fikri"], anlam:"Dünya Fikrî Mülkiyet Örgütü; Paris Sözleşmesi, PCT, Madrid, Lahey gibi anlaşmaları yöneten Birleşmiş Milletler uzmanlık kuruluşu (Cenevre).", ornek:"Madrid sistemindeki uluslararası tescilleri WIPO Uluslararası Bürosu yapar.", kat:"Uluslararası", es:["Dünya Fikrî Mülkiyet Örgütü"]},
  {k:"Yayım ertelemesi", ara:["yayım erteleme","yayımın ertelen"], anlam:"Başvuru sahibinin başvuruyla birlikte talep etmesi hâlinde tasarımın yayımının başvuru veya rüçhan tarihinden itibaren otuz ay süreyle ertelenmesi (SMK m.66).", ornek:"Başvuru sahibi otuz ay süreyle yayım erteleme talebinde bulunabilir.", kat:"Tasarım", ref:"SMK m.66"},
  {k:"Yayıma itiraz", ara:["yayıma itiraz"], anlam:"Bültende yayımlanan bir başvuruya, ilgililerin yayım tarihinden itibaren iki ay içinde Kuruma yaptığı itiraz (SMK m.18).", ornek:"Yayıma itiraz, başvurunun yayımlandığı tarihten itibaren iki ay içinde yapılır.", kat:"Marka", ref:"SMK m.18"},
  {k:"Yenilik", ara:["yenilik"], anlam:"Patentte buluşun tekniğin bilinen durumuna dâhil olmaması (SMK m.83/2); tasarımda ise aynısının daha önce dünyanın herhangi bir yerinde kamuya sunulmamış olması (SMK m.56/4).", ornek:"Tasarımlar sadece küçük ayrıntılarda farklılık gösteriyorsa aynı kabul edilir ve yenilik yoktur.", kat:"Patent", ref:"SMK m.83"},
  {k:"Yetkisiz temsil", ara:["yetkisiz temsil"], anlam:"Temsil yetkisi olmadan veya yetkisini aşarak başkası adına işlem yapma. Temsil olunan onaylamadıkça (icazet vermedikçe) işlem onu bağlamaz (TBK m.46).", ornek:"Yetkisiz temsilcinin yaptığı sözleşme, temsil olunan onaylarsa onu bağlar.", kat:"Genel hukuk"},
  {k:"YİDK", ara:["yeniden inceleme ve değerlendirme"], anlam:"Yeniden İnceleme ve Değerlendirme Kurulu: Kurum kararlarına yapılan itirazları inceleyerek nihai idari kararı veren Kurul; SMK'da kısaca 'Kurul' denir (SMK m.2/1-f).", ornek:"Kurul kararlarına karşı mahkemede dava açılabilir.", kat:"Usul ve yaptırım", ref:"SMK m.2", es:["Kurul"]},
  {k:"Yoksun kalınan kazanç", ara:["yoksun kalınan"], anlam:"Tecavüz olmasaydı hak sahibinin elde edeceği, ancak tecavüz yüzünden kaçırdığı kazanç. Hak sahibinin seçimine göre muhtemel gelir, tecavüz edenin net kazancı veya makul lisans bedeli yöntemiyle hesaplanır (SMK m.151).", ornek:"Yoksun kalınan kazanç, zarar gören hak sahibinin seçimine bağlı olarak hesaplanır.", kat:"Usul ve yaptırım", ref:"SMK m.151", es:["kâr kaybı","mahrum kalınan kâr"]},
  {k:"Yükseköğretim buluşu", ara:["yükseköğretim"], anlam:"Üniversite gibi yükseköğretim kurumlarında bilimsel çalışma sonucu yapılan buluş; çalışan buluşu hükümleri uygulanır ve buluştan elde edilen gelirin en az üçte biri buluşu yapana verilir (SMK m.121).", ornek:"Yükseköğretim kurumunun buluştan elde ettiği gelirin en az üçte biri buluşu yapana verilir.", kat:"Patent", ref:"SMK m.121"},
  {k:"Zabıt kâtibi", ara:["zabıt"], anlam:"Mahkemede tutanakları tutan ve yazı işlerini yürüten görevli.", ornek:"İmha işlemi, emanet memuru ve iki zabıt kâtibinden oluşan komisyon tarafından yerine getirilir.", kat:"Usul ve yaptırım", es:["yazı işleri görevlisi","katip"]},
  {k:"Zamanaşımı", ara:["zamanaşım"], anlam:"Belli bir sürenin geçmesiyle bir alacağın dava yoluyla istenebilme imkânının kalkması; hak tamamen sona ermez, borçlu ancak def'i olarak ileri sürerse dikkate alınır. SMK'dan doğan özel hukuk taleplerinde TBK'nın zamanaşımı hükümleri uygulanır (SMK m.157).", ornek:"Tazminat talepleri, TBK'daki zamanaşımı süreleri geçince istenemez.", kat:"Usul ve yaptırım", ref:"SMK m.157", es:["müruruzaman"]},
  {k:"Zararsız açıklama", ara:["zararsız açıklama"], anlam:"Başvuru veya rüçhan tarihinden önceki on iki ay içinde buluşun buluşu yapan tarafından ya da ondan elde edilen bilgilerle Kurum, resmî makam veya üçüncü kişi tarafından açıklanması; bu açıklama tekniğin bilinen durumunda dikkate alınmaz (SMK m.84).", ornek:"Buluşu yapanın başvurudan altı ay önce fuarda tanıttığı buluş, zararsız açıklama nedeniyle yeniliğini kaybetmez.", kat:"Patent", ref:"SMK m.84", es:["yeniliği etkilemeyen açıklama","grace period"]},
  {k:"Zihni faaliyet", ara:["zihni faaliyet"], anlam:"Zihinsel etkinlik. Zihni faaliyetlere, iş faaliyetlerine veya oyunlara ilişkin plan, kural ve yöntemler buluş sayılmaz (SMK m.82/2-b).", ornek:"Bir satranç stratejisi, zihni faaliyete ilişkin yöntem olduğu için patentlenemez.", kat:"Patent", ref:"SMK m.82", es:["zihinsel faaliyet"]},
  {k:"Zorunlu lisans", ara:["zorunlu lisans"], anlam:"Hak sahibinin rızası aranmaksızın, kanundaki şartlar (kullanmama, patentlerin bağımlılığı, kamu yararı) gerçekleştiğinde verilen ve kural olarak inhisari olmayan lisans (SMK m.129-133).", ornek:"Patent konusu buluşun kullanılmaması hâlinde ilgili herkes zorunlu lisans talep edebilir.", kat:"Patent", ref:"SMK m.129", es:["cebri lisans"]}
];
